INSERT INTO `user_guide` VALUES (1,'System Overview','system-overview','getting-started',1,'<h2>Welcome to KPLC MCLab System</h2>\n        <p>The Meter Central Laboratory System is a comprehensive web-based application designed to manage the entire calibration lifecycle.</p>\n\n        <h3>Key Features</h3>\n        <ul>\n            <li><strong>Customer Management</strong> - Create, edit, and manage customer records</li>\n            <li><strong>Calibration Workflow</strong> - Full lifecycle from request to certificate</li>\n            <li><strong>Test Management</strong> - Record test results with uncertainty calculations</li>\n            <li><strong>Role-Based Access</strong> - Different permissions for different user roles</li>\n            <li><strong>Digital Signatures</strong> - Electronic signatures for certificates</li>\n            <li><strong>Document Generation</strong> - PDF generation for all official documents</li>\n            <li><strong>Equipment Tracking</strong> - Manage laboratory equipment inventory</li>\n            <li><strong>Audit Trail</strong> - Track all system activities</li>\n        </ul>\n\n        <h3>System Roles</h3>\n        <table>\n            <thead><tr><th>Role</th><th>Responsibilities</th></tr></thead>\n            <tbody>\n                <tr><td><strong>Super Admin</strong></td><td>System configuration, user management, overall oversight</td></tr>\n                <tr><td><strong>Lab Manager</strong></td><td>Approve certificates, oversee operations, manage staff</td></tr>\n                <tr><td><strong>Supervisor</strong></td><td>Check certificates, verify test results, quality assurance</td></tr>\n                <tr><td><strong>Lab Technician</strong></td><td>Perform calibrations, record test results, generate certificates</td></tr>\n                <tr><td><strong>Customer Service</strong></td><td>Create customer accounts, manage requests, handle inquiries</td></tr>\n                <tr><td><strong>Customer</strong></td><td>Submit requests, view certificates, track calibration status</td></tr>\n            </tbody>\n        </table>','<h2>Welcome to KPLC MCLab System</h2>\n        <p>The Meter Central Laboratory System is a comprehensive web-based application designed to manage the entire calibration lifecycle.</p>\n\n        <h3>Key Features</h3>\n        <ul>\n            <li><strong>Customer Management</strong> - Create, edit, and manage customer records</li>\n            <li><strong>Calibration Workflow</strong> - Full lifecycle from request to certificate</li>\n            <li><strong>Test Management</strong> - Record test results with uncertainty calculations</li>\n            <li><strong>Role-Based Access</strong> - Different permissions for different user roles</li>\n            <li><strong>Digital Signatures</strong> - Electronic signatures for certificates</li>\n            <li><strong>Document Generation</strong> - PDF generation for all official documents</li>\n            <li><strong>Equipment Tracking</strong> - Manage laboratory equipment inventory</li>\n            <li><strong>Audit Trail</strong> - Track all system activities</li>\n        </ul>\n\n        <h3>System Roles</h3>\n        <table>\n            <thead><tr><th>Role</th><th>Responsibilities</th></tr></thead>\n            <tbody>\n                <tr><td><strong>Super Admin</strong></td><td>System configuration, user management, overall oversight</td></tr>\n                <tr><td><strong>Lab Manager</strong></td><td>Approve certificates, oversee operations, manage staff</td></tr>\n                <tr><td><strong>Supervisor</strong></td><td>Check certificates, verify test results, quality assurance</td></tr>\n                <tr><td><strong>Lab Technician</strong></td><td>Perform calibrations, record test results, generate certificates</td></tr>\n                <tr><td><strong>Customer Service</strong></td><td>Create customer accounts, manage requests, handle inquiries</td></tr>\n                <tr><td><strong>Customer</strong></td><td>Submit requests, view certificates, track calibration status</td></tr>\n            </tbody>\n        </table>',0,'info-circle',1,NULL,1,'2026-06-23 14:21:25','2026-06-23 15:05:02'),(2,'Getting Started Guide','getting-started-guide','getting-started',0,'<h2>Getting Started Guide</h2>\n\n<h3>Login</h3>\n<ol>\n    <li>Navigate to the system URL</li>\n    <li>Enter your credentials:\n        <ul>\n            <li><strong>Email:</strong> your.email@kplc.co.ke</li>\n            <li><strong>Password:</strong> your password</li>\n        </ul>\n    </li>\n    <li>Click <strong>Login</strong></li>\n</ol>\n\n<div class=\"alert alert-info\">\n    <i class=\"fas fa-info-circle\"></i>\n    <strong>Default Test Account:</strong><br>\n    Email: quality@kplc.co.ke<br>\n    Password: Quality@123<br>\n    Role: Quality Controller\n</div>\n\n<h3>Navigation</h3>\n<p>The system uses a two-level navigation system:</p>\n\n<h4>Top Navigation Bar</h4>\n<ul>\n    <li><strong>Dashboard:</strong> Main dashboard</li>\n    <li><strong>Quality:</strong> Quality management dropdown\n        <ul>\n            <li>Dashboard</li>\n            <li>Objectives</li>\n            <li>Achievements</li>\n            <li>Corrective Actions</li>\n            <li>Reports</li>\n        </ul>\n    </li>\n    <li><strong>User Guide:</strong> System documentation</li>\n</ul>\n\n<h4>Sidebar Navigation</h4>\n<p>Quick access to all major features organized by category.</p>\n\n<div class=\"alert alert-success\">\n    <i class=\"fas fa-check-circle\"></i>\n    <strong>Tip:</strong> Use the sidebar for quick navigation and the top menu for dropdown access.\n</div>','<h2>Getting Started Guide</h2>\n\n<h3>Login</h3>\n<ol>\n    <li>Navigate to the system URL</li>\n    <li>Enter your credentials:\n        <ul>\n            <li><strong>Email:</strong> your.email@kplc.co.ke</li>\n            <li><strong>Password:</strong> your password</li>\n        </ul>\n    </li>\n    <li>Click <strong>Login</strong></li>\n</ol>\n\n<div class=\"alert alert-info\">\n    <i class=\"fas fa-info-circle\"></i>\n    <strong>Default Test Account:</strong><br>\n    Email: quality@kplc.co.ke<br>\n    Password: Quality@123<br>\n    Role: Quality Controller\n</div>\n\n<h3>Navigation</h3>\n<p>The system uses a two-level navigation system:</p>\n\n<h4>Top Navigation Bar</h4>\n<ul>\n    <li><strong>Dashboard:</strong> Main dashboard</li>\n    <li><strong>Quality:</strong> Quality management dropdown\n        <ul>\n            <li>Dashboard</li>\n            <li>Objectives</li>\n            <li>Achievements</li>\n            <li>Corrective Actions</li>\n            <li>Reports</li>\n        </ul>\n    </li>\n    <li><strong>User Guide:</strong> System documentation</li>\n</ul>\n\n<h4>Sidebar Navigation</h4>\n<p>Quick access to all major features organized by category.</p>\n\n<div class=\"alert alert-success\">\n    <i class=\"fas fa-check-circle\"></i>\n    <strong>Tip:</strong> Use the sidebar for quick navigation and the top menu for dropdown access.\n</div>',0,NULL,1,NULL,1,'2026-06-23 14:21:25','2026-06-23 14:21:25'),(3,'Dashboard Guide','dashboard-guide','dashboard',0,'<h2>Dashboard Guide</h2>\n\n<h3>Overview</h3>\n<p>The dashboard provides a real-time snapshot of quality performance.</p>\n\n<h3>Dashboard Components</h3>\n\n<h4>KPI Cards</h4>\n<div class=\"table-responsive\">\n    <table class=\"table table-bordered\">\n        <thead>\n            <tr>\n                <th>Card</th>\n                <th>Description</th>\n            </tr>\n        </thead>\n        <tbody>\n            <tr>\n                <td><span class=\"badge bg-primary\">Overall Achievement</span></td>\n                <td>Average performance across all objectives</td>\n            </tr>\n            <tr>\n                <td><span class=\"badge bg-success\">On Track</span></td>\n                <td>Objectives meeting targets (≥95%)</td>\n            </tr>\n            <tr>\n                <td><span class=\"badge bg-warning\">At Risk</span></td>\n                <td>Objectives below target (80-94%)</td>\n            </tr>\n            <tr>\n                <td><span class=\"badge bg-danger\">Not Met</span></td>\n                <td>Objectives significantly below target (&lt;80%)</td>\n            </tr>\n        </tbody>\n    </table>\n</div>\n\n<h4>Quick Actions</h4>\n<ul>\n    <li><strong>New Objective:</strong> Create a new quality objective</li>\n    <li><strong>Record Achievement:</strong> Enter quarterly performance</li>\n    <li><strong>Create CAR:</strong> Open a corrective action</li>\n    <li><strong>Generate Report:</strong> Create quality report</li>\n</ul>\n\n<h3>Dashboard Features</h3>\n<ul>\n    <li><strong>FYR Selector:</strong> Switch between financial years</li>\n    <li><strong>Refresh Button:</strong> Update dashboard data</li>\n    <li><strong>Print/Save:</strong> Print dashboard view</li>\n</ul>','<h2>Dashboard Guide</h2>\n\n<h3>Overview</h3>\n<p>The dashboard provides a real-time snapshot of quality performance.</p>\n\n<h3>Dashboard Components</h3>\n\n<h4>KPI Cards</h4>\n<div class=\"table-responsive\">\n    <table class=\"table table-bordered\">\n        <thead>\n            <tr>\n                <th>Card</th>\n                <th>Description</th>\n            </tr>\n        </thead>\n        <tbody>\n            <tr>\n                <td><span class=\"badge bg-primary\">Overall Achievement</span></td>\n                <td>Average performance across all objectives</td>\n            </tr>\n            <tr>\n                <td><span class=\"badge bg-success\">On Track</span></td>\n                <td>Objectives meeting targets (≥95%)</td>\n            </tr>\n            <tr>\n                <td><span class=\"badge bg-warning\">At Risk</span></td>\n                <td>Objectives below target (80-94%)</td>\n            </tr>\n            <tr>\n                <td><span class=\"badge bg-danger\">Not Met</span></td>\n                <td>Objectives significantly below target (&lt;80%)</td>\n            </tr>\n        </tbody>\n    </table>\n</div>\n\n<h4>Quick Actions</h4>\n<ul>\n    <li><strong>New Objective:</strong> Create a new quality objective</li>\n    <li><strong>Record Achievement:</strong> Enter quarterly performance</li>\n    <li><strong>Create CAR:</strong> Open a corrective action</li>\n    <li><strong>Generate Report:</strong> Create quality report</li>\n</ul>\n\n<h3>Dashboard Features</h3>\n<ul>\n    <li><strong>FYR Selector:</strong> Switch between financial years</li>\n    <li><strong>Refresh Button:</strong> Update dashboard data</li>\n    <li><strong>Print/Save:</strong> Print dashboard view</li>\n</ul>',1,NULL,1,NULL,1,'2026-06-23 14:21:25','2026-06-23 14:24:20'),(4,'Managing Quality Objectives','managing-quality-objectives','objectives',0,'<h2>Managing Quality Objectives</h2>\n\n<h3>Overview</h3>\n<p>Quality objectives are specific, measurable targets that align with the laboratory\'s quality policy and ISO 17025 requirements.</p>\n\n<h3>Creating a New Objective</h3>\n<ol>\n    <li>Navigate to <strong>Quality → Objectives</strong> or click <strong>New Objective</strong></li>\n    <li>Fill in the required fields</li>\n    <li>Click <strong>Create Objective</strong></li>\n</ol>\n\n<h3>Required Fields</h3>\n<div class=\"table-responsive\">\n    <table class=\"table table-bordered\">\n        <thead>\n            <tr>\n                <th>Field</th>\n                <th>Description</th>\n            </tr>\n        </thead>\n        <tbody>\n            <tr>\n                <td><strong>Objective ID</strong></td>\n                <td>Unique identifier (e.g., MCL-001)</td>\n            </tr>\n            <tr>\n                <td><strong>Section</strong></td>\n                <td>MCL, Instruments, or Large Power</td>\n            </tr>\n            <tr>\n                <td><strong>Description</strong></td>\n                <td>Detailed description of the objective</td>\n            </tr>\n            <tr>\n                <td><strong>Unit of Measure</strong></td>\n                <td>Days, Hours, NO., %, Number</td>\n            </tr>\n            <tr>\n                <td><strong>Target Value</strong></td>\n                <td>Numeric target to achieve</td>\n            </tr>\n            <tr>\n                <td><strong>Target FYR</strong></td>\n                <td>Financial year for this objective</td>\n            </tr>\n            <tr>\n                <td><strong>Owner</strong></td>\n                <td>Person responsible</td>\n            </tr>\n        </tbody>\n    </table>\n</div>\n\n<h3>Viewing and Managing Objectives</h3>\n<ul>\n    <li><strong>Search and Filter:</strong> Use filters by section, FYR, status</li>\n    <li><strong>Edit:</strong> Click the edit button to modify objective details</li>\n    <li><strong>Delete:</strong> Remove objective with confirmation</li>\n</ul>','<h2>Managing Quality Objectives</h2>\n\n<h3>Overview</h3>\n<p>Quality objectives are specific, measurable targets that align with the laboratory\'s quality policy and ISO 17025 requirements.</p>\n\n<h3>Creating a New Objective</h3>\n<ol>\n    <li>Navigate to <strong>Quality → Objectives</strong> or click <strong>New Objective</strong></li>\n    <li>Fill in the required fields</li>\n    <li>Click <strong>Create Objective</strong></li>\n</ol>\n\n<h3>Required Fields</h3>\n<div class=\"table-responsive\">\n    <table class=\"table table-bordered\">\n        <thead>\n            <tr>\n                <th>Field</th>\n                <th>Description</th>\n            </tr>\n        </thead>\n        <tbody>\n            <tr>\n                <td><strong>Objective ID</strong></td>\n                <td>Unique identifier (e.g., MCL-001)</td>\n            </tr>\n            <tr>\n                <td><strong>Section</strong></td>\n                <td>MCL, Instruments, or Large Power</td>\n            </tr>\n            <tr>\n                <td><strong>Description</strong></td>\n                <td>Detailed description of the objective</td>\n            </tr>\n            <tr>\n                <td><strong>Unit of Measure</strong></td>\n                <td>Days, Hours, NO., %, Number</td>\n            </tr>\n            <tr>\n                <td><strong>Target Value</strong></td>\n                <td>Numeric target to achieve</td>\n            </tr>\n            <tr>\n                <td><strong>Target FYR</strong></td>\n                <td>Financial year for this objective</td>\n            </tr>\n            <tr>\n                <td><strong>Owner</strong></td>\n                <td>Person responsible</td>\n            </tr>\n        </tbody>\n    </table>\n</div>\n\n<h3>Viewing and Managing Objectives</h3>\n<ul>\n    <li><strong>Search and Filter:</strong> Use filters by section, FYR, status</li>\n    <li><strong>Edit:</strong> Click the edit button to modify objective details</li>\n    <li><strong>Delete:</strong> Remove objective with confirmation</li>\n</ul>',0,NULL,1,NULL,1,'2026-06-23 14:21:25','2026-06-23 14:21:25'),(5,'Recording Achievements','recording-achievements','achievements',0,'<h2>Recording Achievements</h2>\n\n<h3>Overview</h3>\n<p>Quarterly achievements record actual performance against objectives for each quarter of the FYR.</p>\n\n<h3>Recording an Achievement</h3>\n<ol>\n    <li>Navigate to <strong>Quality → Achievements</strong></li>\n    <li>Click <strong>Record Achievement</strong></li>\n    <li>Select the objective, FYR, and quarter</li>\n    <li>Enter the actual achievement value</li>\n    <li>Click <strong>Save Achievement</strong></li>\n</ol>\n\n<h3>Bulk Entry</h3>\n<ol>\n    <li>Navigate to <strong>Quality → Achievements</strong></li>\n    <li>Click <strong>Bulk Entry</strong></li>\n    <li>Select FYR and Quarter</li>\n    <li>Enter values for multiple objectives</li>\n    <li>Click <strong>Save All Achievements</strong></li>\n</ol>\n\n<h3>Achievement Status</h3>\n<div class=\"table-responsive\">\n    <table class=\"table table-bordered\">\n        <thead>\n            <tr>\n                <th>Status</th>\n                <th>Criteria</th>\n                <th>Color</th>\n            </tr>\n        </thead>\n        <tbody>\n            <tr>\n                <td><span class=\"badge bg-success\">On Track</span></td>\n                <td>≥95% of target</td>\n                <td>Green</td>\n            </tr>\n            <tr>\n                <td><span class=\"badge bg-warning\">At Risk</span></td>\n                <td>80-94% of target</td>\n                <td>Yellow</td>\n            </tr>\n            <tr>\n                <td><span class=\"badge bg-danger\">Not Met</span></td>\n                <td>&lt;80% of target</td>\n                <td>Red</td>\n            </tr>\n            <tr>\n                <td><span class=\"badge bg-secondary\">Pending</span></td>\n                <td>No data recorded</td>\n                <td>Gray</td>\n            </tr>\n        </tbody>\n    </table>\n</div>','<h2>Recording Achievements</h2>\n\n<h3>Overview</h3>\n<p>Quarterly achievements record actual performance against objectives for each quarter of the FYR.</p>\n\n<h3>Recording an Achievement</h3>\n<ol>\n    <li>Navigate to <strong>Quality → Achievements</strong></li>\n    <li>Click <strong>Record Achievement</strong></li>\n    <li>Select the objective, FYR, and quarter</li>\n    <li>Enter the actual achievement value</li>\n    <li>Click <strong>Save Achievement</strong></li>\n</ol>\n\n<h3>Bulk Entry</h3>\n<ol>\n    <li>Navigate to <strong>Quality → Achievements</strong></li>\n    <li>Click <strong>Bulk Entry</strong></li>\n    <li>Select FYR and Quarter</li>\n    <li>Enter values for multiple objectives</li>\n    <li>Click <strong>Save All Achievements</strong></li>\n</ol>\n\n<h3>Achievement Status</h3>\n<div class=\"table-responsive\">\n    <table class=\"table table-bordered\">\n        <thead>\n            <tr>\n                <th>Status</th>\n                <th>Criteria</th>\n                <th>Color</th>\n            </tr>\n        </thead>\n        <tbody>\n            <tr>\n                <td><span class=\"badge bg-success\">On Track</span></td>\n                <td>≥95% of target</td>\n                <td>Green</td>\n            </tr>\n            <tr>\n                <td><span class=\"badge bg-warning\">At Risk</span></td>\n                <td>80-94% of target</td>\n                <td>Yellow</td>\n            </tr>\n            <tr>\n                <td><span class=\"badge bg-danger\">Not Met</span></td>\n                <td>&lt;80% of target</td>\n                <td>Red</td>\n            </tr>\n            <tr>\n                <td><span class=\"badge bg-secondary\">Pending</span></td>\n                <td>No data recorded</td>\n                <td>Gray</td>\n            </tr>\n        </tbody>\n    </table>\n</div>',2,NULL,1,NULL,1,'2026-06-23 14:21:25','2026-06-23 15:32:39'),(6,'Managing Corrective Actions','managing-corrective-actions','corrective-actions',0,'<h2>Managing Corrective Actions (CARs)</h2>\n\n<h3>Overview</h3>\n<p>Corrective Actions document and track actions taken to address quality issues or non-conformances.</p>\n\n<h3>CAR Lifecycle</h3>\n<div class=\"text-center my-4\">\n    <div class=\"d-flex justify-content-center align-items-center\">\n        <span class=\"badge bg-danger p-3 mx-2\">Open</span>\n        <i class=\"fas fa-arrow-right\"></i>\n        <span class=\"badge bg-warning p-3 mx-2\">In Progress</span>\n        <i class=\"fas fa-arrow-right\"></i>\n        <span class=\"badge bg-success p-3 mx-2\">Closed</span>\n    </div>\n</div>\n\n<h3>Creating a CAR</h3>\n<ol>\n    <li>Navigate to <strong>Quality → Corrective Actions</strong></li>\n    <li>Click <strong>New Corrective Action</strong></li>\n    <li>Fill in the required fields</li>\n    <li>Click <strong>Create CAR</strong></li>\n</ol>\n\n<h3>Managing CARs</h3>\n<ul>\n    <li><strong>Open → In Progress:</strong> Click \"Start Progress\"</li>\n    <li><strong>In Progress → Closed:</strong> Click \"Approve & Close\"</li>\n</ul>\n\n<h3>CAR Status Colors</h3>\n<div class=\"table-responsive\">\n    <table class=\"table table-bordered\">\n        <thead>\n            <tr>\n                <th>Status</th>\n                <th>Color</th>\n                <th>Meaning</th>\n            </tr>\n        </thead>\n        <tbody>\n            <tr>\n                <td><span class=\"badge bg-danger\">Open</span></td>\n                <td>Red</td>\n                <td>Issue identified, action needed</td>\n            </tr>\n            <tr>\n                <td><span class=\"badge bg-warning\">In Progress</span></td>\n                <td>Yellow</td>\n                <td>Action being taken</td>\n            </tr>\n            <tr>\n                <td><span class=\"badge bg-success\">Closed</span></td>\n                <td>Green</td>\n                <td>Issue resolved</td>\n            </tr>\n        </tbody>\n    </table>\n</div>','<h2>Managing Corrective Actions (CARs)</h2>\n\n<h3>Overview</h3>\n<p>Corrective Actions document and track actions taken to address quality issues or non-conformances.</p>\n\n<h3>CAR Lifecycle</h3>\n<div class=\"text-center my-4\">\n    <div class=\"d-flex justify-content-center align-items-center\">\n        <span class=\"badge bg-danger p-3 mx-2\">Open</span>\n        <i class=\"fas fa-arrow-right\"></i>\n        <span class=\"badge bg-warning p-3 mx-2\">In Progress</span>\n        <i class=\"fas fa-arrow-right\"></i>\n        <span class=\"badge bg-success p-3 mx-2\">Closed</span>\n    </div>\n</div>\n\n<h3>Creating a CAR</h3>\n<ol>\n    <li>Navigate to <strong>Quality → Corrective Actions</strong></li>\n    <li>Click <strong>New Corrective Action</strong></li>\n    <li>Fill in the required fields</li>\n    <li>Click <strong>Create CAR</strong></li>\n</ol>\n\n<h3>Managing CARs</h3>\n<ul>\n    <li><strong>Open → In Progress:</strong> Click \"Start Progress\"</li>\n    <li><strong>In Progress → Closed:</strong> Click \"Approve & Close\"</li>\n</ul>\n\n<h3>CAR Status Colors</h3>\n<div class=\"table-responsive\">\n    <table class=\"table table-bordered\">\n        <thead>\n            <tr>\n                <th>Status</th>\n                <th>Color</th>\n                <th>Meaning</th>\n            </tr>\n        </thead>\n        <tbody>\n            <tr>\n                <td><span class=\"badge bg-danger\">Open</span></td>\n                <td>Red</td>\n                <td>Issue identified, action needed</td>\n            </tr>\n            <tr>\n                <td><span class=\"badge bg-warning\">In Progress</span></td>\n                <td>Yellow</td>\n                <td>Action being taken</td>\n            </tr>\n            <tr>\n                <td><span class=\"badge bg-success\">Closed</span></td>\n                <td>Green</td>\n                <td>Issue resolved</td>\n            </tr>\n        </tbody>\n    </table>\n</div>',1,NULL,1,NULL,1,'2026-06-23 14:21:25','2026-06-23 15:25:45'),(7,'Generating Reports','generating-reports','reports',1,'<h2>Generating Reports</h2>\n\n        <h3>Available Reports</h3>\n        <ul>\n            <li><strong>Calibrations Report</strong> - View and export calibration data</li>\n            <li><strong>Customers Report</strong> - Customer activity and calibration statistics</li>\n            <li><strong>Certificates Report</strong> - Certificate generation and status</li>\n            <li><strong>Equipment Report</strong> - Laboratory equipment inventory</li>\n        </ul>\n\n        <h3>Steps to Generate a Report</h3>\n        <ol>\n            <li>Navigate to <strong>Reports</strong></li>\n            <li>Select the report type</li>\n            <li>Apply filters (date range, status, etc.)</li>\n            <li>Click <strong>Generate Report</strong></li>\n            <li>Export to PDF or Excel if needed</li>\n        </ol>','<h2>Generating Reports</h2>\n\n        <h3>Available Reports</h3>\n        <ul>\n            <li><strong>Calibrations Report</strong> - View and export calibration data</li>\n            <li><strong>Customers Report</strong> - Customer activity and calibration statistics</li>\n            <li><strong>Certificates Report</strong> - Certificate generation and status</li>\n            <li><strong>Equipment Report</strong> - Laboratory equipment inventory</li>\n        </ul>\n\n        <h3>Steps to Generate a Report</h3>\n        <ol>\n            <li>Navigate to <strong>Reports</strong></li>\n            <li>Select the report type</li>\n            <li>Apply filters (date range, status, etc.)</li>\n            <li>Click <strong>Generate Report</strong></li>\n            <li>Export to PDF or Excel if needed</li>\n        </ol>',3,'chart-bar',1,NULL,1,'2026-06-23 14:21:25','2026-06-29 08:36:28'),(8,'Frequently Asked Questions','faq','faq',1,'<h2>Frequently Asked Questions</h2>\n\n        <div class=\"accordion\" id=\"faqAccordion\">\n            <div class=\"accordion-item\">\n                <h3 class=\"accordion-header\">\n                    <button class=\"accordion-button\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#faq1\">\n                        How do I reset my password?\n                    </button>\n                </h3>\n                <div id=\"faq1\" class=\"accordion-collapse collapse show\">\n                    <div class=\"accordion-body\">\n                        Click \"Forgot Password\" on the login page and follow the instructions.\n                    </div>\n                </div>\n            </div>\n            <div class=\"accordion-item\">\n                <h3 class=\"accordion-header\">\n                    <button class=\"accordion-button collapsed\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#faq2\">\n                        Why can\'t I add test results?\n                    </button>\n                </h3>\n                <div id=\"faq2\" class=\"accordion-collapse collapse\">\n                    <div class=\"accordion-body\">\n                        You must be the assigned technician and the calibration must be in \"Assigned\" or \"In Progress\" status.\n                    </div>\n                </div>\n            </div>\n            <div class=\"accordion-item\">\n                <h3 class=\"accordion-header\">\n                    <button class=\"accordion-button collapsed\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#faq3\">\n                        How many trial readings are required?\n                    </button>\n                </h3>\n                <div id=\"faq3\" class=\"accordion-collapse collapse\">\n                    <div class=\"accordion-body\">\n                        You need exactly 10 trial readings for accurate uncertainty calculation.\n                    </div>\n                </div>\n            </div>\n            <div class=\"accordion-item\">\n                <h3 class=\"accordion-header\">\n                    <button class=\"accordion-button collapsed\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#faq4\">\n                        What is the default tolerance value?\n                    </button>\n                </h3>\n                <div id=\"faq4\" class=\"accordion-collapse collapse\">\n                    <div class=\"accordion-body\">\n                        The default tolerance is 0.5%. You can adjust it up to a maximum of 1%.\n                    </div>\n                </div>\n            </div>\n            <div class=\"accordion-item\">\n                <h3 class=\"accordion-header\">\n                    <button class=\"accordion-button collapsed\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#faq5\">\n                        How is uncertainty calculated?\n                    </button>\n                </h3>\n                <div id=\"faq5\" class=\"accordion-collapse collapse\">\n                    <div class=\"accordion-body\">\n                        Uncertainty is calculated using u₁ (repeatability), u₂ (reference standard), and u₃ (UUT resolution) components with a 95% confidence level (k=2).\n                    </div>\n                </div>\n            </div>\n            <div class=\"accordion-item\">\n                <h3 class=\"accordion-header\">\n                    <button class=\"accordion-button collapsed\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#faq6\">\n                        Can I edit test results after saving?\n                    </button>\n                </h3>\n                <div id=\"faq6\" class=\"accordion-collapse collapse\">\n                    <div class=\"accordion-body\">\n                        Yes, you can edit test results using the Edit (✏️) button in the test results list.\n                    </div>\n                </div>\n            </div>\n            <div class=\"accordion-item\">\n                <h3 class=\"accordion-header\">\n                    <button class=\"accordion-button collapsed\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#faq7\">\n                        Why can\'t I generate a certificate?\n                    </button>\n                </h3>\n                <div id=\"faq7\" class=\"accordion-collapse collapse\">\n                    <div class=\"accordion-body\">\n                        The calibration must be in \"Completed\" status and all test results must be recorded with uncertainty calculations.\n                    </div>\n                </div>\n            </div>\n        </div>','<h2>Frequently Asked Questions</h2>\n\n        <div class=\"accordion\" id=\"faqAccordion\">\n            <div class=\"accordion-item\">\n                <h3 class=\"accordion-header\">\n                    <button class=\"accordion-button\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#faq1\">\n                        How do I reset my password?\n                    </button>\n                </h3>\n                <div id=\"faq1\" class=\"accordion-collapse collapse show\">\n                    <div class=\"accordion-body\">\n                        Click \"Forgot Password\" on the login page and follow the instructions.\n                    </div>\n                </div>\n            </div>\n            <div class=\"accordion-item\">\n                <h3 class=\"accordion-header\">\n                    <button class=\"accordion-button collapsed\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#faq2\">\n                        Why can\'t I add test results?\n                    </button>\n                </h3>\n                <div id=\"faq2\" class=\"accordion-collapse collapse\">\n                    <div class=\"accordion-body\">\n                        You must be the assigned technician and the calibration must be in \"Assigned\" or \"In Progress\" status.\n                    </div>\n                </div>\n            </div>\n            <div class=\"accordion-item\">\n                <h3 class=\"accordion-header\">\n                    <button class=\"accordion-button collapsed\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#faq3\">\n                        How many trial readings are required?\n                    </button>\n                </h3>\n                <div id=\"faq3\" class=\"accordion-collapse collapse\">\n                    <div class=\"accordion-body\">\n                        You need exactly 10 trial readings for accurate uncertainty calculation.\n                    </div>\n                </div>\n            </div>\n            <div class=\"accordion-item\">\n                <h3 class=\"accordion-header\">\n                    <button class=\"accordion-button collapsed\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#faq4\">\n                        What is the default tolerance value?\n                    </button>\n                </h3>\n                <div id=\"faq4\" class=\"accordion-collapse collapse\">\n                    <div class=\"accordion-body\">\n                        The default tolerance is 0.5%. You can adjust it up to a maximum of 1%.\n                    </div>\n                </div>\n            </div>\n            <div class=\"accordion-item\">\n                <h3 class=\"accordion-header\">\n                    <button class=\"accordion-button collapsed\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#faq5\">\n                        How is uncertainty calculated?\n                    </button>\n                </h3>\n                <div id=\"faq5\" class=\"accordion-collapse collapse\">\n                    <div class=\"accordion-body\">\n                        Uncertainty is calculated using u₁ (repeatability), u₂ (reference standard), and u₃ (UUT resolution) components with a 95% confidence level (k=2).\n                    </div>\n                </div>\n            </div>\n            <div class=\"accordion-item\">\n                <h3 class=\"accordion-header\">\n                    <button class=\"accordion-button collapsed\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#faq6\">\n                        Can I edit test results after saving?\n                    </button>\n                </h3>\n                <div id=\"faq6\" class=\"accordion-collapse collapse\">\n                    <div class=\"accordion-body\">\n                        Yes, you can edit test results using the Edit (✏️) button in the test results list.\n                    </div>\n                </div>\n            </div>\n            <div class=\"accordion-item\">\n                <h3 class=\"accordion-header\">\n                    <button class=\"accordion-button collapsed\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#faq7\">\n                        Why can\'t I generate a certificate?\n                    </button>\n                </h3>\n                <div id=\"faq7\" class=\"accordion-collapse collapse\">\n                    <div class=\"accordion-body\">\n                        The calibration must be in \"Completed\" status and all test results must be recorded with uncertainty calculations.\n                    </div>\n                </div>\n            </div>\n        </div>',0,'question',1,NULL,1,'2026-06-23 14:21:25','2026-06-23 15:05:02'),(9,'Troubleshooting Guide','troubleshooting-guide','troubleshooting',0,'<h2>Troubleshooting Guide</h2>\n\n<h3>Common Issues</h3>\n\n<h4>Login Issues</h4>\n<div class=\"table-responsive\">\n    <table class=\"table table-bordered\">\n        <thead>\n            <tr>\n                <th>Issue</th>\n                <th>Solution</th>\n            </tr>\n        </thead>\n        <tbody>\n            <tr>\n                <td>Incorrect password</td>\n                <td>Reset password via administrator</td>\n            </tr>\n            <tr>\n                <td>Account locked</td>\n                <td>Contact system administrator</td>\n            </tr>\n            <tr>\n                <td>Access denied</td>\n                <td>Verify user role and permissions</td>\n            </tr>\n        </tbody>\n    </table>\n</div>\n\n<h4>Dashboard Issues</h4>\n<div class=\"table-responsive\">\n    <table class=\"table table-bordered\">\n        <thead>\n            <tr>\n                <th>Issue</th>\n                <th>Solution</th>\n            </tr>\n        </thead>\n        <tbody>\n            <tr>\n                <td>No data displayed</td>\n                <td>Ensure objectives have been created</td>\n            </tr>\n            <tr>\n                <td>Charts not loading</td>\n                <td>Refresh page or clear browser cache</td>\n            </tr>\n            <tr>\n                <td>Slow performance</td>\n                <td>Reduce data range or use filters</td>\n            </tr>\n        </tbody>\n    </table>\n</div>\n\n<h3>Error Messages</h3>\n<div class=\"table-responsive\">\n    <table class=\"table table-bordered\">\n        <thead>\n            <tr>\n                <th>Error</th>\n                <th>Meaning</th>\n                <th>Action</th>\n            </tr>\n        </thead>\n        <tbody>\n            <tr>\n                <td>\"Duplicate entry\"</td>\n                <td>Record already exists</td>\n                <td>Check for existing record</td>\n            </tr>\n            <tr>\n                <td>\"View not found\"</td>\n                <td>Missing template</td>\n                <td>Contact administrator</td>\n            </tr>\n            <tr>\n                <td>\"Permission denied\"</td>\n                <td>Insufficient access</td>\n                <td>Verify user role</td>\n            </tr>\n        </tbody>\n    </table>\n</div>\n\n<h3>Performance Tips</h3>\n<ol>\n    <li><strong>Use Filters:</strong> Filter data to improve load times</li>\n    <li><strong>Clear Cache:</strong> Regularly clear browser cache</li>\n    <li><strong>Modern Browser:</strong> Use updated Chrome or Firefox</li>\n    <li><strong>Check Permissions:</strong> Verify access rights</li>\n</ol>','<h2>Troubleshooting Guide</h2>\n\n<h3>Common Issues</h3>\n\n<h4>Login Issues</h4>\n<div class=\"table-responsive\">\n    <table class=\"table table-bordered\">\n        <thead>\n            <tr>\n                <th>Issue</th>\n                <th>Solution</th>\n            </tr>\n        </thead>\n        <tbody>\n            <tr>\n                <td>Incorrect password</td>\n                <td>Reset password via administrator</td>\n            </tr>\n            <tr>\n                <td>Account locked</td>\n                <td>Contact system administrator</td>\n            </tr>\n            <tr>\n                <td>Access denied</td>\n                <td>Verify user role and permissions</td>\n            </tr>\n        </tbody>\n    </table>\n</div>\n\n<h4>Dashboard Issues</h4>\n<div class=\"table-responsive\">\n    <table class=\"table table-bordered\">\n        <thead>\n            <tr>\n                <th>Issue</th>\n                <th>Solution</th>\n            </tr>\n        </thead>\n        <tbody>\n            <tr>\n                <td>No data displayed</td>\n                <td>Ensure objectives have been created</td>\n            </tr>\n            <tr>\n                <td>Charts not loading</td>\n                <td>Refresh page or clear browser cache</td>\n            </tr>\n            <tr>\n                <td>Slow performance</td>\n                <td>Reduce data range or use filters</td>\n            </tr>\n        </tbody>\n    </table>\n</div>\n\n<h3>Error Messages</h3>\n<div class=\"table-responsive\">\n    <table class=\"table table-bordered\">\n        <thead>\n            <tr>\n                <th>Error</th>\n                <th>Meaning</th>\n                <th>Action</th>\n            </tr>\n        </thead>\n        <tbody>\n            <tr>\n                <td>\"Duplicate entry\"</td>\n                <td>Record already exists</td>\n                <td>Check for existing record</td>\n            </tr>\n            <tr>\n                <td>\"View not found\"</td>\n                <td>Missing template</td>\n                <td>Contact administrator</td>\n            </tr>\n            <tr>\n                <td>\"Permission denied\"</td>\n                <td>Insufficient access</td>\n                <td>Verify user role</td>\n            </tr>\n        </tbody>\n    </table>\n</div>\n\n<h3>Performance Tips</h3>\n<ol>\n    <li><strong>Use Filters:</strong> Filter data to improve load times</li>\n    <li><strong>Clear Cache:</strong> Regularly clear browser cache</li>\n    <li><strong>Modern Browser:</strong> Use updated Chrome or Firefox</li>\n    <li><strong>Check Permissions:</strong> Verify access rights</li>\n</ol>',0,NULL,1,NULL,1,'2026-06-23 14:21:25','2026-06-23 14:21:25'),(10,'Glossary of Terms','glossary-of-terms','glossary',0,'<h2>Glossary of Terms</h2>\n\n<div class=\"table-responsive\">\n    <table class=\"table table-bordered table-striped\">\n        <thead>\n            <tr>\n                <th>Term</th>\n                <th>Definition</th>\n            </tr>\n        </thead>\n        <tbody>\n            <tr>\n                <td><strong>FYR</strong></td>\n                <td>Financial Year (July-June)</td>\n            </tr>\n            <tr>\n                <td><strong>QMS</strong></td>\n                <td>Quality Management System</td>\n            </tr>\n            <tr>\n                <td><strong>CAR</strong></td>\n                <td>Corrective Action Request</td>\n            </tr>\n            <tr>\n                <td><strong>MCL</strong></td>\n                <td>Meter Central Laboratory</td>\n            </tr>\n            <tr>\n                <td><strong>TAT</strong></td>\n                <td>Turnaround Time</td>\n            </tr>\n            <tr>\n                <td><strong>KPI</strong></td>\n                <td>Key Performance Indicator</td>\n            </tr>\n            <tr>\n                <td><strong>ISO</strong></td>\n                <td>International Organization for Standardization</td>\n            </tr>\n            <tr>\n                <td><strong>ISO 17025</strong></td>\n                <td>General requirements for the competence of testing and calibration laboratories</td>\n            </tr>\n            <tr>\n                <td><strong>Non-conformance</strong></td>\n                <td>Failure to meet specified requirements</td>\n            </tr>\n            <tr>\n                <td><strong>Root Cause</strong></td>\n                <td>The underlying reason for a non-conformance</td>\n            </tr>\n            <tr>\n                <td><strong>Corrective Action</strong></td>\n                <td>Action to eliminate the cause of a non-conformance</td>\n            </tr>\n        </tbody>\n    </table>\n</div>','<h2>Glossary of Terms</h2>\n\n<div class=\"table-responsive\">\n    <table class=\"table table-bordered table-striped\">\n        <thead>\n            <tr>\n                <th>Term</th>\n                <th>Definition</th>\n            </tr>\n        </thead>\n        <tbody>\n            <tr>\n                <td><strong>FYR</strong></td>\n                <td>Financial Year (July-June)</td>\n            </tr>\n            <tr>\n                <td><strong>QMS</strong></td>\n                <td>Quality Management System</td>\n            </tr>\n            <tr>\n                <td><strong>CAR</strong></td>\n                <td>Corrective Action Request</td>\n            </tr>\n            <tr>\n                <td><strong>MCL</strong></td>\n                <td>Meter Central Laboratory</td>\n            </tr>\n            <tr>\n                <td><strong>TAT</strong></td>\n                <td>Turnaround Time</td>\n            </tr>\n            <tr>\n                <td><strong>KPI</strong></td>\n                <td>Key Performance Indicator</td>\n            </tr>\n            <tr>\n                <td><strong>ISO</strong></td>\n                <td>International Organization for Standardization</td>\n            </tr>\n            <tr>\n                <td><strong>ISO 17025</strong></td>\n                <td>General requirements for the competence of testing and calibration laboratories</td>\n            </tr>\n            <tr>\n                <td><strong>Non-conformance</strong></td>\n                <td>Failure to meet specified requirements</td>\n            </tr>\n            <tr>\n                <td><strong>Root Cause</strong></td>\n                <td>The underlying reason for a non-conformance</td>\n            </tr>\n            <tr>\n                <td><strong>Corrective Action</strong></td>\n                <td>Action to eliminate the cause of a non-conformance</td>\n            </tr>\n        </tbody>\n    </table>\n</div>',0,NULL,1,NULL,1,'2026-06-23 14:21:25','2026-06-23 14:21:25'),(11,'User Roles & Permissions','user-roles-permissions','user-roles',0,'<h2>User Roles & Permissions</h2>\n\n<h3>Role Overview</h3>\n<div class=\"table-responsive\">\n    <table class=\"table table-bordered\">\n        <thead>\n            <tr>\n                <th>Role</th>\n                <th>Description</th>\n                <th>Access Level</th>\n            </tr>\n        </thead>\n        <tbody>\n            <tr>\n                <td><span class=\"badge bg-danger\">Super Admin</span></td>\n                <td>Full system access</td>\n                <td>All features</td>\n            </tr>\n            <tr>\n                <td><span class=\"badge bg-primary\">Admin</span></td>\n                <td>System administration</td>\n                <td>User management, audit logs</td>\n            </tr>\n            <tr>\n                <td><span class=\"badge bg-info\">Lab Manager</span></td>\n                <td>Lab management</td>\n                <td>Full quality management</td>\n            </tr>\n            <tr>\n                <td><span class=\"badge bg-success\">Quality Controller</span></td>\n                <td>Quality operations</td>\n                <td>Full quality features</td>\n            </tr>\n            <tr>\n                <td><span class=\"badge bg-secondary\">Supervisor</span></td>\n                <td>Team supervision</td>\n                <td>View and create</td>\n            </tr>\n            <tr>\n                <td><span class=\"badge bg-secondary\">Lab Technician</span></td>\n                <td>Technical operations</td>\n                <td>Basic access</td>\n            </tr>\n            <tr>\n                <td><span class=\"badge bg-secondary\">Customer</span></td>\n                <td>External user</td>\n                <td>Limited access</td>\n            </tr>\n        </tbody>\n    </table>\n</div>\n\n<h3>Quality Controller Permissions</h3>\n<div class=\"table-responsive\">\n    <table class=\"table table-bordered\">\n        <thead>\n            <tr>\n                <th>Module</th>\n                <th>Permissions</th>\n            </tr>\n        </thead>\n        <tbody>\n            <tr>\n                <td><strong>Dashboard</strong></td>\n                <td>View</td>\n            </tr>\n            <tr>\n                <td><strong>Objectives</strong></td>\n                <td>View, Create, Edit, Delete</td>\n            </tr>\n            <tr>\n                <td><strong>Achievements</strong></td>\n                <td>View, Create, Edit, Delete, Bulk Entry</td>\n            </tr>\n            <tr>\n                <td><strong>Corrective Actions</strong></td>\n                <td>View, Create, Edit, Delete, Approve</td>\n            </tr>\n            <tr>\n                <td><strong>Reports</strong></td>\n                <td>View, Generate, Export</td>\n            </tr>\n        </tbody>\n    </table>\n</div>\n\n<h3>Role Assignment</h3>\n<p>Roles are assigned by Super Admin or Admin users through:</p>\n<ol>\n    <li><strong>Users</strong> → <strong>Edit User</strong></li>\n    <li>Select role from dropdown</li>\n    <li>Save changes</li>\n</ol>','<h2>User Roles & Permissions</h2>\n\n<h3>Role Overview</h3>\n<div class=\"table-responsive\">\n    <table class=\"table table-bordered\">\n        <thead>\n            <tr>\n                <th>Role</th>\n                <th>Description</th>\n                <th>Access Level</th>\n            </tr>\n        </thead>\n        <tbody>\n            <tr>\n                <td><span class=\"badge bg-danger\">Super Admin</span></td>\n                <td>Full system access</td>\n                <td>All features</td>\n            </tr>\n            <tr>\n                <td><span class=\"badge bg-primary\">Admin</span></td>\n                <td>System administration</td>\n                <td>User management, audit logs</td>\n            </tr>\n            <tr>\n                <td><span class=\"badge bg-info\">Lab Manager</span></td>\n                <td>Lab management</td>\n                <td>Full quality management</td>\n            </tr>\n            <tr>\n                <td><span class=\"badge bg-success\">Quality Controller</span></td>\n                <td>Quality operations</td>\n                <td>Full quality features</td>\n            </tr>\n            <tr>\n                <td><span class=\"badge bg-secondary\">Supervisor</span></td>\n                <td>Team supervision</td>\n                <td>View and create</td>\n            </tr>\n            <tr>\n                <td><span class=\"badge bg-secondary\">Lab Technician</span></td>\n                <td>Technical operations</td>\n                <td>Basic access</td>\n            </tr>\n            <tr>\n                <td><span class=\"badge bg-secondary\">Customer</span></td>\n                <td>External user</td>\n                <td>Limited access</td>\n            </tr>\n        </tbody>\n    </table>\n</div>\n\n<h3>Quality Controller Permissions</h3>\n<div class=\"table-responsive\">\n    <table class=\"table table-bordered\">\n        <thead>\n            <tr>\n                <th>Module</th>\n                <th>Permissions</th>\n            </tr>\n        </thead>\n        <tbody>\n            <tr>\n                <td><strong>Dashboard</strong></td>\n                <td>View</td>\n            </tr>\n            <tr>\n                <td><strong>Objectives</strong></td>\n                <td>View, Create, Edit, Delete</td>\n            </tr>\n            <tr>\n                <td><strong>Achievements</strong></td>\n                <td>View, Create, Edit, Delete, Bulk Entry</td>\n            </tr>\n            <tr>\n                <td><strong>Corrective Actions</strong></td>\n                <td>View, Create, Edit, Delete, Approve</td>\n            </tr>\n            <tr>\n                <td><strong>Reports</strong></td>\n                <td>View, Generate, Export</td>\n            </tr>\n        </tbody>\n    </table>\n</div>\n\n<h3>Role Assignment</h3>\n<p>Roles are assigned by Super Admin or Admin users through:</p>\n<ol>\n    <li><strong>Users</strong> → <strong>Edit User</strong></li>\n    <li>Select role from dropdown</li>\n    <li>Save changes</li>\n</ol>',1,NULL,1,NULL,1,'2026-06-23 14:21:25','2026-06-23 15:16:11'),(12,'Getting Support','getting-support','support',0,'<h2>Getting Support</h2>\n\n<h3>Getting Help</h3>\n<ul>\n    <li><strong>System Administrator:</strong> For login, permissions, and technical issues</li>\n    <li><strong>Lab Manager:</strong> For quality processes and procedures</li>\n    <li><strong>Quality Manager:</strong> For quality policy and ISO compliance</li>\n</ul>\n\n<h3>Contact Information</h3>\n<div class=\"table-responsive\">\n    <table class=\"table table-bordered\">\n        <thead>\n            <tr>\n                <th>Role</th>\n                <th>Email</th>\n                <th>Purpose</th>\n            </tr>\n        </thead>\n        <tbody>\n            <tr>\n                <td><strong>System Admin</strong></td>\n                <td>admin@kplc.co.ke</td>\n                <td>Technical support</td>\n            </tr>\n            <tr>\n                <td><strong>Lab Manager</strong></td>\n                <td>labmanager@kplc.co.ke</td>\n                <td>Quality procedures</td>\n            </tr>\n            <tr>\n                <td><strong>Quality Manager</strong></td>\n                <td>quality@kplc.co.ke</td>\n                <td>Quality policy</td>\n            </tr>\n        </tbody>\n    </table>\n</div>\n\n<h3>Training Resources</h3>\n<ul>\n    <li><strong>User Guide:</strong> This documentation</li>\n    <li><strong>Video Tutorials:</strong> Available upon request</li>\n    <li><strong>Training Sessions:</strong> Scheduled as needed</li>\n    <li><strong>Quick Reference Cards:</strong> Available for key tasks</li>\n</ul>\n\n<div class=\"alert alert-info mt-4\">\n    <i class=\"fas fa-info-circle\"></i>\n    <strong>Document Version:</strong> 1.0<br>\n    <strong>Last Updated:</strong> June 23, 2026<br>\n    <strong>Prepared By:</strong> Quality Management Team\n</div>','<h2>Getting Support</h2>\n\n<h3>Getting Help</h3>\n<ul>\n    <li><strong>System Administrator:</strong> For login, permissions, and technical issues</li>\n    <li><strong>Lab Manager:</strong> For quality processes and procedures</li>\n    <li><strong>Quality Manager:</strong> For quality policy and ISO compliance</li>\n</ul>\n\n<h3>Contact Information</h3>\n<div class=\"table-responsive\">\n    <table class=\"table table-bordered\">\n        <thead>\n            <tr>\n                <th>Role</th>\n                <th>Email</th>\n                <th>Purpose</th>\n            </tr>\n        </thead>\n        <tbody>\n            <tr>\n                <td><strong>System Admin</strong></td>\n                <td>admin@kplc.co.ke</td>\n                <td>Technical support</td>\n            </tr>\n            <tr>\n                <td><strong>Lab Manager</strong></td>\n                <td>labmanager@kplc.co.ke</td>\n                <td>Quality procedures</td>\n            </tr>\n            <tr>\n                <td><strong>Quality Manager</strong></td>\n                <td>quality@kplc.co.ke</td>\n                <td>Quality policy</td>\n            </tr>\n        </tbody>\n    </table>\n</div>\n\n<h3>Training Resources</h3>\n<ul>\n    <li><strong>User Guide:</strong> This documentation</li>\n    <li><strong>Video Tutorials:</strong> Available upon request</li>\n    <li><strong>Training Sessions:</strong> Scheduled as needed</li>\n    <li><strong>Quick Reference Cards:</strong> Available for key tasks</li>\n</ul>\n\n<div class=\"alert alert-info mt-4\">\n    <i class=\"fas fa-info-circle\"></i>\n    <strong>Document Version:</strong> 1.0<br>\n    <strong>Last Updated:</strong> June 23, 2026<br>\n    <strong>Prepared By:</strong> Quality Management Team\n</div>',0,NULL,1,NULL,1,'2026-06-23 14:21:25','2026-06-23 14:21:25'),(13,'How to Login','how-to-login','getting-started',2,'<h2>How to Login to the System</h2>\n\n        <h3>Step 1: Open Your Browser</h3>\n        <p>Open Google Chrome (recommended), Mozilla Firefox, or Microsoft Edge.</p>\n\n        <h3>Step 2: Navigate to the System</h3>\n        <p>Enter the system URL in your browser\'s address bar.</p>\n\n        <h3>Step 3: Enter Your Credentials</h3>\n        <p>Enter your registered email and password.</p>\n\n        <h3>Default Login Credentials</h3>\n        <table>\n            <thead><tr><th>Role</th><th>Email</th><th>Password</th></tr></thead>\n            <tbody>\n                <tr><td>Super Admin</td><td>admin@kplc.co.ke</td><td>Admin@123</td></tr>\n                <tr><td>Lab Manager</td><td>labmanager@kplc.co.ke</td><td>Manager@123</td></tr>\n                <tr><td>Supervisor</td><td>supervisor@kplc.co.ke</td><td>Supervisor@123</td></tr>\n                <tr><td>Technician</td><td>tech@kplc.co.ke</td><td>Tech@123</td></tr>\n            </tbody>\n        </table>\n\n        <div class=\"alert alert-warning\">\n            <strong>⚠️ Important:</strong> Change your password immediately after first login!\n        </div>','<h2>How to Login to the System</h2>\n\n        <h3>Step 1: Open Your Browser</h3>\n        <p>Open Google Chrome (recommended), Mozilla Firefox, or Microsoft Edge.</p>\n\n        <h3>Step 2: Navigate to the System</h3>\n        <p>Enter the system URL in your browser\'s address bar.</p>\n\n        <h3>Step 3: Enter Your Credentials</h3>\n        <p>Enter your registered email and password.</p>\n\n        <h3>Default Login Credentials</h3>\n        <table>\n            <thead><tr><th>Role</th><th>Email</th><th>Password</th></tr></thead>\n            <tbody>\n                <tr><td>Super Admin</td><td>admin@kplc.co.ke</td><td>Admin@123</td></tr>\n                <tr><td>Lab Manager</td><td>labmanager@kplc.co.ke</td><td>Manager@123</td></tr>\n                <tr><td>Supervisor</td><td>supervisor@kplc.co.ke</td><td>Supervisor@123</td></tr>\n                <tr><td>Technician</td><td>tech@kplc.co.ke</td><td>Tech@123</td></tr>\n            </tbody>\n        </table>\n\n        <div class=\"alert alert-warning\">\n            <strong>⚠️ Important:</strong> Change your password immediately after first login!\n        </div>',0,'sign-in-alt',1,NULL,1,'2026-06-23 15:05:02','2026-06-23 15:05:02'),(14,'Dashboard Overview','dashboard-overview','getting-started',3,'<h2>Dashboard Overview</h2>\n        <p>The Dashboard provides a quick overview of system statistics and activities.</p>\n\n        <h3>Dashboard Components</h3>\n        <ul>\n            <li><strong>Statistics Cards</strong> - Quick overview of calibration counts</li>\n            <li><strong>Recent Activities</strong> - Latest calibrations and updates</li>\n            <li><strong>Equipment Gallery</strong> - Display of laboratory equipment</li>\n            <li><strong>Quick Actions</strong> - Create new calibration, add customer</li>\n        </ul>','<h2>Dashboard Overview</h2>\n        <p>The Dashboard provides a quick overview of system statistics and activities.</p>\n\n        <h3>Dashboard Components</h3>\n        <ul>\n            <li><strong>Statistics Cards</strong> - Quick overview of calibration counts</li>\n            <li><strong>Recent Activities</strong> - Latest calibrations and updates</li>\n            <li><strong>Equipment Gallery</strong> - Display of laboratory equipment</li>\n            <li><strong>Quick Actions</strong> - Create new calibration, add customer</li>\n        </ul>',0,'tachometer-alt',1,NULL,1,'2026-06-23 15:05:02','2026-06-23 15:05:02'),(15,'Creating a New Customer','creating-customer','customers',1,'<h2>Creating a New Customer</h2>\n\n        <h3>Navigation</h3>\n        <p>Main Menu → Customers → Add Customer</p>\n\n        <h3>Step 1: Fill Customer Details</h3>\n        <table>\n            <thead><tr><th>Field</th><th>Required</th><th>Description</th></tr></thead>\n            <tbody>\n                <tr><td>Company Name</td><td>✅ Yes</td><td>Full company name</td></tr>\n                <tr><td>Contact Person</td><td>✅ Yes</td><td>Primary contact name</td></tr>\n                <tr><td>Phone</td><td>✅ Yes</td><td>Contact phone number</td></tr>\n                <tr><td>Email</td><td>❌ No</td><td>Customer email (for notifications)</td></tr>\n                <tr><td>Address</td><td>✅ Yes</td><td>Physical address</td></tr>\n                <tr><td>Tax ID (PIN)</td><td>❌ No</td><td>KRA PIN number</td></tr>\n            </tbody>\n        </table>\n\n        <h3>Step 2: Click \"Create Customer\"</h3>\n        <p>Review all information and click the <strong>Create Customer</strong> button.</p>','<h2>Creating a New Customer</h2>\n\n        <h3>Navigation</h3>\n        <p>Main Menu → Customers → Add Customer</p>\n\n        <h3>Step 1: Fill Customer Details</h3>\n        <table>\n            <thead><tr><th>Field</th><th>Required</th><th>Description</th></tr></thead>\n            <tbody>\n                <tr><td>Company Name</td><td>✅ Yes</td><td>Full company name</td></tr>\n                <tr><td>Contact Person</td><td>✅ Yes</td><td>Primary contact name</td></tr>\n                <tr><td>Phone</td><td>✅ Yes</td><td>Contact phone number</td></tr>\n                <tr><td>Email</td><td>❌ No</td><td>Customer email (for notifications)</td></tr>\n                <tr><td>Address</td><td>✅ Yes</td><td>Physical address</td></tr>\n                <tr><td>Tax ID (PIN)</td><td>❌ No</td><td>KRA PIN number</td></tr>\n            </tbody>\n        </table>\n\n        <h3>Step 2: Click \"Create Customer\"</h3>\n        <p>Review all information and click the <strong>Create Customer</strong> button.</p>',0,'user-plus',1,NULL,1,'2026-06-23 15:05:02','2026-06-23 15:05:02'),(16,'Managing Customers','managing-customers','customers',2,'<h2>Managing Customers</h2>\n\n        <h3>Viewing Customers</h3>\n        <p>Main Menu → Customers</p>\n\n        <h3>Editing a Customer</h3>\n        <ol>\n            <li>Navigate to <strong>Customers</strong></li>\n            <li>Click the <strong>Edit (✏️)</strong> button next to the customer</li>\n            <li>Update the required fields</li>\n            <li>Click <strong>Update Customer</strong></li>\n        </ol>\n\n        <h3>Viewing Customer Details</h3>\n        <p>Click on a customer row to view:</p>\n        <ul>\n            <li>Company information</li>\n            <li>Contact details</li>\n            <li>Calibration history</li>\n            <li>Equipment list</li>\n            <li>Certificate history</li>\n        </ul>','<h2>Managing Customers</h2>\n\n        <h3>Viewing Customers</h3>\n        <p>Main Menu → Customers</p>\n\n        <h3>Editing a Customer</h3>\n        <ol>\n            <li>Navigate to <strong>Customers</strong></li>\n            <li>Click the <strong>Edit (✏️)</strong> button next to the customer</li>\n            <li>Update the required fields</li>\n            <li>Click <strong>Update Customer</strong></li>\n        </ol>\n\n        <h3>Viewing Customer Details</h3>\n        <p>Click on a customer row to view:</p>\n        <ul>\n            <li>Company information</li>\n            <li>Contact details</li>\n            <li>Calibration history</li>\n            <li>Equipment list</li>\n            <li>Certificate history</li>\n        </ul>',0,'users-cog',1,NULL,1,'2026-06-23 15:05:02','2026-06-23 15:05:02'),(17,'Creating a Calibration Request','creating-calibration','calibrations',1,'<h2>Creating a Calibration Request</h2>\n\n        <h3>Navigation</h3>\n        <p>Main Menu → Calibrations → New Calibration</p>\n\n        <h3>Step 1: Select Customer</h3>\n        <ul>\n            <li>Choose the customer from the dropdown list</li>\n            <li>If customer doesn\'t exist, create one first</li>\n        </ul>\n\n        <h3>Step 2: Enter Equipment Details</h3>\n        <table>\n            <thead><tr><th>Field</th><th>Required</th><th>Description</th></tr></thead>\n            <tbody>\n                <tr><td>Equipment Name</td><td>✅ Yes</td><td>Name of equipment</td></tr>\n                <tr><td>Serial Number</td><td>✅ Yes</td><td>Unique serial number</td></tr>\n                <tr><td>Manufacturer</td><td>❌ No</td><td>Equipment manufacturer</td></tr>\n                <tr><td>Model</td><td>❌ No</td><td>Equipment model</td></tr>\n                <tr><td>Condition</td><td>✅ Yes</td><td>Excellent/Good/Fair/Poor/Damaged</td></tr>\n            </tbody>\n        </table>\n\n        <h3>Step 3: Click \"Create Calibration\"</h3>\n        <p>Review all information and click the <strong>Create Calibration</strong> button.</p>','<h2>Creating a Calibration Request</h2>\n\n        <h3>Navigation</h3>\n        <p>Main Menu → Calibrations → New Calibration</p>\n\n        <h3>Step 1: Select Customer</h3>\n        <ul>\n            <li>Choose the customer from the dropdown list</li>\n            <li>If customer doesn\'t exist, create one first</li>\n        </ul>\n\n        <h3>Step 2: Enter Equipment Details</h3>\n        <table>\n            <thead><tr><th>Field</th><th>Required</th><th>Description</th></tr></thead>\n            <tbody>\n                <tr><td>Equipment Name</td><td>✅ Yes</td><td>Name of equipment</td></tr>\n                <tr><td>Serial Number</td><td>✅ Yes</td><td>Unique serial number</td></tr>\n                <tr><td>Manufacturer</td><td>❌ No</td><td>Equipment manufacturer</td></tr>\n                <tr><td>Model</td><td>❌ No</td><td>Equipment model</td></tr>\n                <tr><td>Condition</td><td>✅ Yes</td><td>Excellent/Good/Fair/Poor/Damaged</td></tr>\n            </tbody>\n        </table>\n\n        <h3>Step 3: Click \"Create Calibration\"</h3>\n        <p>Review all information and click the <strong>Create Calibration</strong> button.</p>',0,'plus-circle',1,NULL,1,'2026-06-23 15:05:02','2026-06-23 15:05:02'),(18,'Assigning a Technician','assigning-technician','calibrations',2,'<h2>Assigning a Technician</h2>\n\n        <h3>Navigation</h3>\n        <p>Open the calibration details → Click Assign Technician</p>\n\n        <h3>Steps</h3>\n        <ol>\n            <li>Open the calibration details</li>\n            <li>Click <strong>Assign Technician</strong></li>\n            <li>Select a technician from the dropdown</li>\n            <li>Add assignment notes (optional)</li>\n            <li>Click <strong>Assign Technician</strong></li>\n        </ol>\n\n        <div class=\"alert alert-info\">\n            <strong>Note:</strong> Only technicians with the appropriate role will appear in the dropdown.\n        </div>','<h2>Assigning a Technician</h2>\n\n        <h3>Navigation</h3>\n        <p>Open the calibration details → Click Assign Technician</p>\n\n        <h3>Steps</h3>\n        <ol>\n            <li>Open the calibration details</li>\n            <li>Click <strong>Assign Technician</strong></li>\n            <li>Select a technician from the dropdown</li>\n            <li>Add assignment notes (optional)</li>\n            <li>Click <strong>Assign Technician</strong></li>\n        </ol>\n\n        <div class=\"alert alert-info\">\n            <strong>Note:</strong> Only technicians with the appropriate role will appear in the dropdown.\n        </div>',0,'user-check',1,NULL,1,'2026-06-23 15:05:02','2026-06-23 15:05:02'),(19,'Calibration Status Flow','calibration-status-flow','calibrations',3,'<h2>Calibration Status Flow</h2>\n\n        <h3>External Customers</h3>\n        <div class=\"bg-light p-3 rounded\">\n            <p class=\"text-center\">\n                Pending → Quoted → Paid → Assigned → In Progress → Testing → Completed → Certified\n            </p>\n        </div>\n\n        <h3>Internal (KPLC) Customers</h3>\n        <div class=\"bg-light p-3 rounded\">\n            <p class=\"text-center\">\n                Pending → Assigned → In Progress → Testing → Completed → Certified\n            </p>\n        </div>\n\n        <h3>Status Descriptions</h3>\n        <table>\n            <thead><tr><th>Status</th><th>Description</th></tr></thead>\n            <tbody>\n                <tr><td>Pending</td><td>Calibration request submitted</td></tr>\n                <tr><td>Quoted</td><td>Quote sent to customer (External)</td></tr>\n                <tr><td>Paid</td><td>Payment received (External)</td></tr>\n                <tr><td>Assigned</td><td>Technician assigned</td></tr>\n                <tr><td>In Progress</td><td>Work started</td></tr>\n                <tr><td>Testing</td><td>Testing in progress</td></tr>\n                <tr><td>Completed</td><td>Testing complete, ready for certificate</td></tr>\n                <tr><td>Certified</td><td>Certificate generated and sent</td></tr>\n            </tbody>\n        </table>','<h2>Calibration Status Flow</h2>\n\n        <h3>External Customers</h3>\n        <div class=\"bg-light p-3 rounded\">\n            <p class=\"text-center\">\n                Pending → Quoted → Paid → Assigned → In Progress → Testing → Completed → Certified\n            </p>\n        </div>\n\n        <h3>Internal (KPLC) Customers</h3>\n        <div class=\"bg-light p-3 rounded\">\n            <p class=\"text-center\">\n                Pending → Assigned → In Progress → Testing → Completed → Certified\n            </p>\n        </div>\n\n        <h3>Status Descriptions</h3>\n        <table>\n            <thead><tr><th>Status</th><th>Description</th></tr></thead>\n            <tbody>\n                <tr><td>Pending</td><td>Calibration request submitted</td></tr>\n                <tr><td>Quoted</td><td>Quote sent to customer (External)</td></tr>\n                <tr><td>Paid</td><td>Payment received (External)</td></tr>\n                <tr><td>Assigned</td><td>Technician assigned</td></tr>\n                <tr><td>In Progress</td><td>Work started</td></tr>\n                <tr><td>Testing</td><td>Testing in progress</td></tr>\n                <tr><td>Completed</td><td>Testing complete, ready for certificate</td></tr>\n                <tr><td>Certified</td><td>Certificate generated and sent</td></tr>\n            </tbody>\n        </table>',0,'project-diagram',1,NULL,1,'2026-06-23 15:05:02','2026-06-23 15:05:02'),(20,'Adding Test Results','adding-test-results','test-management',1,'<h2>Adding Test Results</h2>\n\n        <h3>Prerequisites</h3>\n        <ul>\n            <li>You must be the <strong>assigned technician</strong></li>\n            <li>Calibration must be in <strong>\"Assigned\"</strong> or <strong>\"In Progress\"</strong> status</li>\n        </ul>\n\n        <h3>Navigation</h3>\n        <p>Calibrations → [Select Calibration] → Tests → Add Test Result</p>\n\n        <h3>Step 1: Enter Test Information</h3>\n        <table>\n            <thead><tr><th>Field</th><th>Required</th><th>Description</th></tr></thead>\n            <tbody>\n                <tr><td>Test Name</td><td>✅ Yes</td><td>E.g., \"Accuracy at 0.05 Ib, 1.0PF\"</td></tr>\n                <tr><td>Test Type</td><td>✅ Yes</td><td>Accuracy, Register, Starting Current, Creep</td></tr>\n                <tr><td>Applied Value</td><td>❌ No</td><td>E.g., \"0.05Ib(0.5A);1PF;230V;50HZ\"</td></tr>\n                <tr><td>Power Factor</td><td>❌ No</td><td>1.0PF, 0.5LAG, 0.5LEAD</td></tr>\n                <tr><td>Load Type</td><td>❌ No</td><td>Low Load, Base Load, Inductive Load, Maximum Load</td></tr>\n                <tr><td>Voltage</td><td>❌ No</td><td>E.g., \"230V\"</td></tr>\n                <tr><td>Frequency</td><td>❌ No</td><td>E.g., \"50HZ\"</td></tr>\n            </tbody>\n        </table>\n\n        <h3>Step 2: Enter Test Results</h3>\n        <ul>\n            <li><strong>Tolerance:</strong> Default 0.5%, adjustable up to 1%</li>\n            <li><strong>Trial Data:</strong> Enter 10 readings for uncertainty calculation</li>\n            <li>Click <strong>Calculate Uncertainty</strong> to auto-calculate values</li>\n        </ul>\n\n        <h3>Step 3: Save</h3>\n        <p>Click <strong>Save Test Result</strong> to save the test.</p>\n\n        <div class=\"alert alert-success\">\n            <strong>✅ Tip:</strong> The system will auto-set PASS/FAIL based on the tolerance and error value.\n        </div>','<h2>Adding Test Results</h2>\n\n        <h3>Prerequisites</h3>\n        <ul>\n            <li>You must be the <strong>assigned technician</strong></li>\n            <li>Calibration must be in <strong>\"Assigned\"</strong> or <strong>\"In Progress\"</strong> status</li>\n        </ul>\n\n        <h3>Navigation</h3>\n        <p>Calibrations → [Select Calibration] → Tests → Add Test Result</p>\n\n        <h3>Step 1: Enter Test Information</h3>\n        <table>\n            <thead><tr><th>Field</th><th>Required</th><th>Description</th></tr></thead>\n            <tbody>\n                <tr><td>Test Name</td><td>✅ Yes</td><td>E.g., \"Accuracy at 0.05 Ib, 1.0PF\"</td></tr>\n                <tr><td>Test Type</td><td>✅ Yes</td><td>Accuracy, Register, Starting Current, Creep</td></tr>\n                <tr><td>Applied Value</td><td>❌ No</td><td>E.g., \"0.05Ib(0.5A);1PF;230V;50HZ\"</td></tr>\n                <tr><td>Power Factor</td><td>❌ No</td><td>1.0PF, 0.5LAG, 0.5LEAD</td></tr>\n                <tr><td>Load Type</td><td>❌ No</td><td>Low Load, Base Load, Inductive Load, Maximum Load</td></tr>\n                <tr><td>Voltage</td><td>❌ No</td><td>E.g., \"230V\"</td></tr>\n                <tr><td>Frequency</td><td>❌ No</td><td>E.g., \"50HZ\"</td></tr>\n            </tbody>\n        </table>\n\n        <h3>Step 2: Enter Test Results</h3>\n        <ul>\n            <li><strong>Tolerance:</strong> Default 0.5%, adjustable up to 1%</li>\n            <li><strong>Trial Data:</strong> Enter 10 readings for uncertainty calculation</li>\n            <li>Click <strong>Calculate Uncertainty</strong> to auto-calculate values</li>\n        </ul>\n\n        <h3>Step 3: Save</h3>\n        <p>Click <strong>Save Test Result</strong> to save the test.</p>\n\n        <div class=\"alert alert-success\">\n            <strong>✅ Tip:</strong> The system will auto-set PASS/FAIL based on the tolerance and error value.\n        </div>',0,'flask',1,NULL,1,'2026-06-23 15:05:02','2026-06-23 15:05:02'),(21,'Understanding Uncertainty Calculation','uncertainty-calculation','test-management',2,'<h2>Understanding Uncertainty Calculation</h2>\n\n        <h3>What is Measurement Uncertainty?</h3>\n        <p>Measurement uncertainty quantifies the doubt about the result of a measurement. It indicates the range of values within which the true value is expected to lie with a certain confidence level.</p>\n\n        <h3>Uncertainty Components</h3>\n        <table>\n            <thead><tr><th>Component</th><th>Description</th><th>Formula</th></tr></thead>\n            <tbody>\n                <tr><td><strong>u₁</strong></td><td>Repeatability (Type A)</td><td>s / √n</td></tr>\n                <tr><td><strong>u₂</strong></td><td>Reference Standard (Type B)</td><td>RefStd / 2</td></tr>\n                <tr><td><strong>u₃</strong></td><td>UUT Resolution (Type B)</td><td>(Resolution / 2) / √3</td></tr>\n            </tbody>\n        </table>\n\n        <h3>Reference Standard Values</h3>\n        <table>\n            <thead><tr><th>Load Type</th><th>Reference Standard Value</th></tr></thead>\n            <tbody>\n                <tr><td>Low Load (0.05 Ib)</td><td>0.0769%</td></tr>\n                <tr><td>Base Load (Ib)</td><td>0.1041%</td></tr>\n                <tr><td>Inductive Load (Ib)</td><td>0.0768%</td></tr>\n                <tr><td>Maximum Load (IMAX)</td><td>0.1178%</td></tr>\n            </tbody>\n        </table>\n\n        <h3>Formulas</h3>\n        <div class=\"bg-light p-3 rounded\">\n            <p><strong>Combined Uncertainty:</strong> uc = √(u₁² + u₂² + u₃²)</p>\n            <p><strong>Expanded Uncertainty:</strong> U = uc × 2 (95% confidence level)</p>\n        </div>\n\n        <h3>Example Calculation</h3>\n        <p><strong>Trial Data:</strong> 0.20, 0.21, 0.22, 0.21, 0.20, 0.22, 0.21, 0.20, 0.21, 0.22</p>\n        <ul>\n            <li><strong>Average Error:</strong> 0.2090%</li>\n            <li><strong>u₁:</strong> 0.0026%</li>\n            <li><strong>u₂:</strong> 0.0521% (Base Load)</li>\n            <li><strong>u₃:</strong> 0.0289%</li>\n            <li><strong>Combined (uc):</strong> 0.0482%</li>\n            <li><strong>Expanded (U):</strong> 0.0964%</li>\n        </ul>','<h2>Understanding Uncertainty Calculation</h2>\n\n        <h3>What is Measurement Uncertainty?</h3>\n        <p>Measurement uncertainty quantifies the doubt about the result of a measurement. It indicates the range of values within which the true value is expected to lie with a certain confidence level.</p>\n\n        <h3>Uncertainty Components</h3>\n        <table>\n            <thead><tr><th>Component</th><th>Description</th><th>Formula</th></tr></thead>\n            <tbody>\n                <tr><td><strong>u₁</strong></td><td>Repeatability (Type A)</td><td>s / √n</td></tr>\n                <tr><td><strong>u₂</strong></td><td>Reference Standard (Type B)</td><td>RefStd / 2</td></tr>\n                <tr><td><strong>u₃</strong></td><td>UUT Resolution (Type B)</td><td>(Resolution / 2) / √3</td></tr>\n            </tbody>\n        </table>\n\n        <h3>Reference Standard Values</h3>\n        <table>\n            <thead><tr><th>Load Type</th><th>Reference Standard Value</th></tr></thead>\n            <tbody>\n                <tr><td>Low Load (0.05 Ib)</td><td>0.0769%</td></tr>\n                <tr><td>Base Load (Ib)</td><td>0.1041%</td></tr>\n                <tr><td>Inductive Load (Ib)</td><td>0.0768%</td></tr>\n                <tr><td>Maximum Load (IMAX)</td><td>0.1178%</td></tr>\n            </tbody>\n        </table>\n\n        <h3>Formulas</h3>\n        <div class=\"bg-light p-3 rounded\">\n            <p><strong>Combined Uncertainty:</strong> uc = √(u₁² + u₂² + u₃²)</p>\n            <p><strong>Expanded Uncertainty:</strong> U = uc × 2 (95% confidence level)</p>\n        </div>\n\n        <h3>Example Calculation</h3>\n        <p><strong>Trial Data:</strong> 0.20, 0.21, 0.22, 0.21, 0.20, 0.22, 0.21, 0.20, 0.21, 0.22</p>\n        <ul>\n            <li><strong>Average Error:</strong> 0.2090%</li>\n            <li><strong>u₁:</strong> 0.0026%</li>\n            <li><strong>u₂:</strong> 0.0521% (Base Load)</li>\n            <li><strong>u₃:</strong> 0.0289%</li>\n            <li><strong>Combined (uc):</strong> 0.0482%</li>\n            <li><strong>Expanded (U):</strong> 0.0964%</li>\n        </ul>',0,'calculator',1,NULL,1,'2026-06-23 15:05:02','2026-06-23 15:05:02'),(22,'Tolerance and PASS/FAIL Determination','tolerance-pass-fail','test-management',3,'<h2>Tolerance and PASS/FAIL Determination</h2>\n\n        <h3>Tolerance Settings</h3>\n        <ul>\n            <li><strong>Default:</strong> 0.5%</li>\n            <li><strong>Minimum:</strong> 0.1%</li>\n            <li><strong>Maximum:</strong> 1.0%</li>\n        </ul>\n\n        <h3>How PASS/FAIL is Determined</h3>\n        <div class=\"bg-light p-3 rounded\">\n            <p><strong>PASS:</strong> |Error| ≤ Tolerance</p>\n            <p><strong>FAIL:</strong> |Error| > Tolerance</p>\n        </div>\n\n        <h3>Examples</h3>\n        <table>\n            <thead><tr><th>Error Value</th><th>Tolerance</th><th>Result</th></tr></thead>\n            <tbody>\n                <tr><td>0.209%</td><td>0.5%</td><td><span class=\"badge bg-success\">PASS</span></td></tr>\n                <tr><td>0.450%</td><td>0.5%</td><td><span class=\"badge bg-success\">PASS</span></td></tr>\n                <tr><td>0.750%</td><td>0.5%</td><td><span class=\"badge bg-danger\">FAIL</span></td></tr>\n                <tr><td>0.209%</td><td>0.2%</td><td><span class=\"badge bg-danger\">FAIL</span></td></tr>\n                <tr><td>0.150%</td><td>0.2%</td><td><span class=\"badge bg-success\">PASS</span></td></tr>\n            </tbody>\n        </table>\n\n        <div class=\"alert alert-info\">\n            <strong>💡 Tip:</strong> The result is auto-set when you click \"Calculate Uncertainty\".\n        </div>','<h2>Tolerance and PASS/FAIL Determination</h2>\n\n        <h3>Tolerance Settings</h3>\n        <ul>\n            <li><strong>Default:</strong> 0.5%</li>\n            <li><strong>Minimum:</strong> 0.1%</li>\n            <li><strong>Maximum:</strong> 1.0%</li>\n        </ul>\n\n        <h3>How PASS/FAIL is Determined</h3>\n        <div class=\"bg-light p-3 rounded\">\n            <p><strong>PASS:</strong> |Error| ≤ Tolerance</p>\n            <p><strong>FAIL:</strong> |Error| > Tolerance</p>\n        </div>\n\n        <h3>Examples</h3>\n        <table>\n            <thead><tr><th>Error Value</th><th>Tolerance</th><th>Result</th></tr></thead>\n            <tbody>\n                <tr><td>0.209%</td><td>0.5%</td><td><span class=\"badge bg-success\">PASS</span></td></tr>\n                <tr><td>0.450%</td><td>0.5%</td><td><span class=\"badge bg-success\">PASS</span></td></tr>\n                <tr><td>0.750%</td><td>0.5%</td><td><span class=\"badge bg-danger\">FAIL</span></td></tr>\n                <tr><td>0.209%</td><td>0.2%</td><td><span class=\"badge bg-danger\">FAIL</span></td></tr>\n                <tr><td>0.150%</td><td>0.2%</td><td><span class=\"badge bg-success\">PASS</span></td></tr>\n            </tbody>\n        </table>\n\n        <div class=\"alert alert-info\">\n            <strong>💡 Tip:</strong> The result is auto-set when you click \"Calculate Uncertainty\".\n        </div>',1,'balance-scale',1,NULL,1,'2026-06-23 15:05:02','2026-07-20 19:39:33'),(23,'Viewing and Managing Test Results','managing-test-results','test-management',4,'<h2>Viewing and Managing Test Results</h2>\n\n        <h3>Viewing Test Results</h3>\n        <p>Navigation: Calibrations → [Select Calibration] → Tests → View All</p>\n\n        <h3>Test Results Table</h3>\n        <table>\n            <thead><tr><th>Column</th><th>Description</th></tr></thead>\n            <tbody>\n                <tr><td>Test Information</td><td>Test name, type, power factor, voltage, frequency</td></tr>\n                <tr><td>Applied Value</td><td>Test conditions applied</td></tr>\n                <tr><td>Error %</td><td>Average error from trial data</td></tr>\n                <tr><td>Uncertainty</td><td>Expanded uncertainty (U)</td></tr>\n                <tr><td>Result</td><td>PASS or FAIL</td></tr>\n                <tr><td>Actions</td><td>View, Edit, Delete</td></tr>\n            </tbody>\n        </table>\n\n        <h3>Viewing Test Details</h3>\n        <ol>\n            <li>Click the <strong>View (👁️)</strong> button</li>\n            <li>A modal will show:\n                <ul>\n                    <li>Complete test information</li>\n                    <li>Uncertainty components (u₁, u₂, u₃, combined, expanded)</li>\n                    <li>Trial data (10 readings)</li>\n                    <li>Register test details (if applicable)</li>\n                    <li>Notes and metadata</li>\n                </ul>\n            </li>\n        </ol>\n\n        <h3>Editing a Test Result</h3>\n        <ol>\n            <li>Click the <strong>Edit (✏️)</strong> button</li>\n            <li>Update the required fields</li>\n            <li>Click <strong>Update Test Result</strong></li>\n        </ol>\n\n        <h3>Deleting a Test Result</h3>\n        <ol>\n            <li>Click the <strong>Delete (🗑️)</strong> button</li>\n            <li>Confirm deletion</li>\n        </ol>\n\n        <div class=\"alert alert-warning\">\n            <strong>⚠️ Warning:</strong> Deleting a test result also deletes its uncertainty calculation. This action cannot be undone.\n        </div>','<h2>Viewing and Managing Test Results</h2>\n\n        <h3>Viewing Test Results</h3>\n        <p>Navigation: Calibrations → [Select Calibration] → Tests → View All</p>\n\n        <h3>Test Results Table</h3>\n        <table>\n            <thead><tr><th>Column</th><th>Description</th></tr></thead>\n            <tbody>\n                <tr><td>Test Information</td><td>Test name, type, power factor, voltage, frequency</td></tr>\n                <tr><td>Applied Value</td><td>Test conditions applied</td></tr>\n                <tr><td>Error %</td><td>Average error from trial data</td></tr>\n                <tr><td>Uncertainty</td><td>Expanded uncertainty (U)</td></tr>\n                <tr><td>Result</td><td>PASS or FAIL</td></tr>\n                <tr><td>Actions</td><td>View, Edit, Delete</td></tr>\n            </tbody>\n        </table>\n\n        <h3>Viewing Test Details</h3>\n        <ol>\n            <li>Click the <strong>View (👁️)</strong> button</li>\n            <li>A modal will show:\n                <ul>\n                    <li>Complete test information</li>\n                    <li>Uncertainty components (u₁, u₂, u₃, combined, expanded)</li>\n                    <li>Trial data (10 readings)</li>\n                    <li>Register test details (if applicable)</li>\n                    <li>Notes and metadata</li>\n                </ul>\n            </li>\n        </ol>\n\n        <h3>Editing a Test Result</h3>\n        <ol>\n            <li>Click the <strong>Edit (✏️)</strong> button</li>\n            <li>Update the required fields</li>\n            <li>Click <strong>Update Test Result</strong></li>\n        </ol>\n\n        <h3>Deleting a Test Result</h3>\n        <ol>\n            <li>Click the <strong>Delete (🗑️)</strong> button</li>\n            <li>Confirm deletion</li>\n        </ol>\n\n        <div class=\"alert alert-warning\">\n            <strong>⚠️ Warning:</strong> Deleting a test result also deletes its uncertainty calculation. This action cannot be undone.\n        </div>',1,'list-ul',1,NULL,1,'2026-06-23 15:05:02','2026-07-17 19:08:43'),(24,'Quality Controller Dashboard','quality-controller-dashboard','quality-control',1,'<h2>Quality Controller Dashboard</h2>\n\n    <h3>Accessing the Dashboard</h3>\n    <ol>\n        <li>Log in to the system</li>\n        <li>Navigate to <strong>Main Menu → Quality Control</strong></li>\n        <li>The Quality Dashboard will display</li>\n    </ol>\n\n    <h3>Dashboard Components</h3>\n    <table>\n        <thead><tr><th>Component</th><th>Description</th></tr></thead>\n        <tbody>\n            <tr><td>Pending Checks</td><td>Calibrations waiting for quality review</td></tr>\n            <tr><td>Total Checks</td><td>Total calibrations reviewed</td></tr>\n            <tr><td>Passed</td><td>Calibrations that passed quality check</td></tr>\n            <tr><td>Failed</td><td>Calibrations that failed quality check</td></tr>\n            <tr><td>Pending List</td><td>Table showing all pending quality checks</td></tr>\n        </tbody>\n    </table>\n\n    <div class=\"alert alert-info\">\n        <strong>💡 Tip:</strong> The dashboard provides a quick overview of your quality control workload.\n    </div>','<h2>Quality Controller Dashboard</h2>\n\n    <h3>Accessing the Dashboard</h3>\n    <ol>\n        <li>Log in to the system</li>\n        <li>Navigate to <strong>Main Menu → Quality Control</strong></li>\n        <li>The Quality Dashboard will display</li>\n    </ol>\n\n    <h3>Dashboard Components</h3>\n    <table>\n        <thead><tr><th>Component</th><th>Description</th></tr></thead>\n        <tbody>\n            <tr><td>Pending Checks</td><td>Calibrations waiting for quality review</td></tr>\n            <tr><td>Total Checks</td><td>Total calibrations reviewed</td></tr>\n            <tr><td>Passed</td><td>Calibrations that passed quality check</td></tr>\n            <tr><td>Failed</td><td>Calibrations that failed quality check</td></tr>\n            <tr><td>Pending List</td><td>Table showing all pending quality checks</td></tr>\n        </tbody>\n    </table>\n\n    <div class=\"alert alert-info\">\n        <strong>💡 Tip:</strong> The dashboard provides a quick overview of your quality control workload.\n    </div>',2,'tachometer-alt',1,NULL,1,'2026-06-23 15:05:02','2026-07-20 19:39:59'),(25,'Quality Check Process','quality-check-process','quality-control',2,'<h2>Quality Check Process</h2>\n\n    <h3>Accessing a Quality Check</h3>\n    <p><strong>Navigation:</strong> Quality Control → Pending Checks → Click \"Check\"</p>\n\n    <h3>Review Calibration Information</h3>\n    <ul>\n        <li>Customer details</li>\n        <li>Equipment information</li>\n        <li>Serial number</li>\n        <li>Technician assigned</li>\n        <li>Current status</li>\n        <li>Creation date</li>\n    </ul>\n\n    <h3>Test Results Summary</h3>\n    <ul>\n        <li>Total number of tests</li>\n        <li>Passed tests</li>\n        <li>Failed tests</li>\n        <li>Average uncertainty</li>\n    </ul>\n\n    <h3>Quality Checklist</h3>\n    <table>\n        <thead><tr><th>Checklist Item</th><th>Description</th></tr></thead>\n        <tbody>\n            <tr><td>Test Results Complete</td><td>All required tests have been performed</td></tr>\n            <tr><td>Uncertainty Calculated</td><td>Uncertainty has been correctly calculated</td></tr>\n            <tr><td>Traceability Verified</td><td>Measurements are traceable to standards</td></tr>\n            <tr><td>Equipment Calibrated</td><td>MCL equipment is within calibration date</td></tr>\n        </tbody>\n    </table>\n\n    <div class=\"alert alert-warning\">\n        <strong>⚠️ Important:</strong> Always verify all checklist items before making a decision.\n    </div>','<h2>Quality Check Process</h2>\n\n    <h3>Accessing a Quality Check</h3>\n    <p><strong>Navigation:</strong> Quality Control → Pending Checks → Click \"Check\"</p>\n\n    <h3>Review Calibration Information</h3>\n    <ul>\n        <li>Customer details</li>\n        <li>Equipment information</li>\n        <li>Serial number</li>\n        <li>Technician assigned</li>\n        <li>Current status</li>\n        <li>Creation date</li>\n    </ul>\n\n    <h3>Test Results Summary</h3>\n    <ul>\n        <li>Total number of tests</li>\n        <li>Passed tests</li>\n        <li>Failed tests</li>\n        <li>Average uncertainty</li>\n    </ul>\n\n    <h3>Quality Checklist</h3>\n    <table>\n        <thead><tr><th>Checklist Item</th><th>Description</th></tr></thead>\n        <tbody>\n            <tr><td>Test Results Complete</td><td>All required tests have been performed</td></tr>\n            <tr><td>Uncertainty Calculated</td><td>Uncertainty has been correctly calculated</td></tr>\n            <tr><td>Traceability Verified</td><td>Measurements are traceable to standards</td></tr>\n            <tr><td>Equipment Calibrated</td><td>MCL equipment is within calibration date</td></tr>\n        </tbody>\n    </table>\n\n    <div class=\"alert alert-warning\">\n        <strong>⚠️ Important:</strong> Always verify all checklist items before making a decision.\n    </div>',0,'clipboard-check',1,NULL,1,'2026-06-23 15:05:02','2026-06-23 15:05:02'),(26,'Quality Decision Guide','quality-decision-guide','quality-control',3,'<h2>Quality Decision Guide</h2>\n\n    <h3>Decision Options</h3>\n\n    <div class=\"card bg-success text-white p-3 mb-3\">\n        <h4>✅ PASS - Approve Calibration</h4>\n        <ul>\n            <li>Calibration meets all quality standards</li>\n            <li>Certificate can be generated</li>\n            <li>Status changes to \"Completed\"</li>\n        </ul>\n    </div>\n\n    <div class=\"card bg-danger text-white p-3 mb-3\">\n        <h4>❌ FAIL - Reject Calibration</h4>\n        <ul>\n            <li>Calibration does not meet quality standards</li>\n            <li>Certificate cannot be generated</li>\n            <li>Status changes to \"Rejected\"</li>\n            <li>Requires rework or investigation</li>\n        </ul>\n    </div>\n\n    <div class=\"card bg-warning p-3 mb-3\">\n        <h4>🔄 NEEDS REVIEW - Return for Rework</h4>\n        <ul>\n            <li>Issues identified that need correction</li>\n            <li>Calibration returned to technician</li>\n            <li>Status remains \"Testing\"</li>\n            <li>Technician must address issues</li>\n        </ul>\n    </div>\n\n    <h3>Quality Notes</h3>\n    <p>Always provide clear, detailed notes explaining your decision:</p>\n    <ul>\n        <li>What was checked and verified</li>\n        <li>Any issues found</li>\n        <li>Recommendations for improvement</li>\n        <li>References to standards or procedures</li>\n    </ul>','<h2>Quality Decision Guide</h2>\n\n    <h3>Decision Options</h3>\n\n    <div class=\"card bg-success text-white p-3 mb-3\">\n        <h4>✅ PASS - Approve Calibration</h4>\n        <ul>\n            <li>Calibration meets all quality standards</li>\n            <li>Certificate can be generated</li>\n            <li>Status changes to \"Completed\"</li>\n        </ul>\n    </div>\n\n    <div class=\"card bg-danger text-white p-3 mb-3\">\n        <h4>❌ FAIL - Reject Calibration</h4>\n        <ul>\n            <li>Calibration does not meet quality standards</li>\n            <li>Certificate cannot be generated</li>\n            <li>Status changes to \"Rejected\"</li>\n            <li>Requires rework or investigation</li>\n        </ul>\n    </div>\n\n    <div class=\"card bg-warning p-3 mb-3\">\n        <h4>🔄 NEEDS REVIEW - Return for Rework</h4>\n        <ul>\n            <li>Issues identified that need correction</li>\n            <li>Calibration returned to technician</li>\n            <li>Status remains \"Testing\"</li>\n            <li>Technician must address issues</li>\n        </ul>\n    </div>\n\n    <h3>Quality Notes</h3>\n    <p>Always provide clear, detailed notes explaining your decision:</p>\n    <ul>\n        <li>What was checked and verified</li>\n        <li>Any issues found</li>\n        <li>Recommendations for improvement</li>\n        <li>References to standards or procedures</li>\n    </ul>',4,'gavel',1,NULL,1,'2026-06-23 15:05:02','2026-06-23 15:20:00'),(27,'Quality Standards','quality-standards','quality-control',4,'<h2>Quality Standards</h2>\n\n    <h3>Reference Standards</h3>\n    <table>\n        <thead><tr><th>Standard</th><th>Description</th></tr></thead>\n        <tbody>\n            <tr><td>IEC 62052-11</td><td>Electricity metering equipment - General requirements</td></tr>\n            <tr><td>IEC 62058-31</td><td>Electricity metering equipment - Acceptance inspection - Static meters</td></tr>\n        </tbody>\n    </table>\n\n    <h3>Traceability</h3>\n    <p>All measurements must be metrologically traceable through:</p>\n    <ul>\n        <li>Reference standards certificates</li>\n        <li>Calibration dates</li>\n        <li>Equipment serial numbers</li>\n    </ul>\n\n    <h3>Uncertainty Requirements</h3>\n    <ul>\n        <li><strong>Confidence Level:</strong> 95%</li>\n        <li><strong>Coverage Factor:</strong> k = 2</li>\n        <li><strong>Uncertainty Components:</strong>\n            <ul>\n                <li>u₁ (Repeatability)</li>\n                <li>u₂ (Reference Standard)</li>\n                <li>u₃ (UUT Resolution)</li>\n            </ul>\n        </li>\n        <li><strong>Combined Uncertainty:</strong> uc = √(u₁² + u₂² + u₃²)</li>\n        <li><strong>Expanded Uncertainty:</strong> U = uc × 2</li>\n    </ul>\n\n    <div class=\"alert alert-info\">\n        <strong>📚 Note:</strong> Always reference these standards in your quality notes.\n    </div>','<h2>Quality Standards</h2>\n\n    <h3>Reference Standards</h3>\n    <table>\n        <thead><tr><th>Standard</th><th>Description</th></tr></thead>\n        <tbody>\n            <tr><td>IEC 62052-11</td><td>Electricity metering equipment - General requirements</td></tr>\n            <tr><td>IEC 62058-31</td><td>Electricity metering equipment - Acceptance inspection - Static meters</td></tr>\n        </tbody>\n    </table>\n\n    <h3>Traceability</h3>\n    <p>All measurements must be metrologically traceable through:</p>\n    <ul>\n        <li>Reference standards certificates</li>\n        <li>Calibration dates</li>\n        <li>Equipment serial numbers</li>\n    </ul>\n\n    <h3>Uncertainty Requirements</h3>\n    <ul>\n        <li><strong>Confidence Level:</strong> 95%</li>\n        <li><strong>Coverage Factor:</strong> k = 2</li>\n        <li><strong>Uncertainty Components:</strong>\n            <ul>\n                <li>u₁ (Repeatability)</li>\n                <li>u₂ (Reference Standard)</li>\n                <li>u₃ (UUT Resolution)</li>\n            </ul>\n        </li>\n        <li><strong>Combined Uncertainty:</strong> uc = √(u₁² + u₂² + u₃²)</li>\n        <li><strong>Expanded Uncertainty:</strong> U = uc × 2</li>\n    </ul>\n\n    <div class=\"alert alert-info\">\n        <strong>📚 Note:</strong> Always reference these standards in your quality notes.\n    </div>',3,'book',1,NULL,1,'2026-06-23 15:05:02','2026-06-23 15:14:30'),(28,'Quality Reports','quality-reports','quality-control',5,'<h2>Quality Reports</h2>\n\n    <h3>Accessing Quality Reports</h3>\n    <p><strong>Navigation:</strong> Quality Control → View Reports</p>\n\n    <h3>Report Statistics</h3>\n    <table>\n        <thead><tr><th>Statistic</th><th>Description</th></tr></thead>\n        <tbody>\n            <tr><td>Total Checks</td><td>Number of calibrations reviewed</td></tr>\n            <tr><td>Passed</td><td>Calibrations that passed quality check</td></tr>\n            <tr><td>Failed</td><td>Calibrations that failed quality check</td></tr>\n            <tr><td>Pass Rate</td><td>Percentage of calibrations that passed</td></tr>\n        </tbody>\n    </table>\n\n    <h3>Filtering Reports</h3>\n    <p>You can filter reports by:</p>\n    <ul>\n        <li><strong>Date Range</strong> - From Date and To Date</li>\n        <li><strong>Decision</strong> - Passed or Failed</li>\n    </ul>\n\n    <h3>Report Table</h3>\n    <table>\n        <thead><tr><th>Column</th><th>Description</th></tr></thead>\n        <tbody>\n            <tr><td>ID</td><td>Calibration reference number</td></tr>\n            <tr><td>Customer</td><td>Customer company name</td></tr>\n            <tr><td>Equipment</td><td>Equipment name</td></tr>\n            <tr><td>Decision</td><td>Passed/Failed/Pending</td></tr>\n            <tr><td>Checked By</td><td>Quality Controller name</td></tr>\n            <tr><td>Date</td><td>Date of quality check</td></tr>\n        </tbody>\n    </table>\n\n    <div class=\"alert alert-success\">\n        <strong>📊 Tip:</strong> Use reports to track quality trends and identify areas for improvement.\n    </div>','<h2>Quality Reports</h2>\n\n    <h3>Accessing Quality Reports</h3>\n    <p><strong>Navigation:</strong> Quality Control → View Reports</p>\n\n    <h3>Report Statistics</h3>\n    <table>\n        <thead><tr><th>Statistic</th><th>Description</th></tr></thead>\n        <tbody>\n            <tr><td>Total Checks</td><td>Number of calibrations reviewed</td></tr>\n            <tr><td>Passed</td><td>Calibrations that passed quality check</td></tr>\n            <tr><td>Failed</td><td>Calibrations that failed quality check</td></tr>\n            <tr><td>Pass Rate</td><td>Percentage of calibrations that passed</td></tr>\n        </tbody>\n    </table>\n\n    <h3>Filtering Reports</h3>\n    <p>You can filter reports by:</p>\n    <ul>\n        <li><strong>Date Range</strong> - From Date and To Date</li>\n        <li><strong>Decision</strong> - Passed or Failed</li>\n    </ul>\n\n    <h3>Report Table</h3>\n    <table>\n        <thead><tr><th>Column</th><th>Description</th></tr></thead>\n        <tbody>\n            <tr><td>ID</td><td>Calibration reference number</td></tr>\n            <tr><td>Customer</td><td>Customer company name</td></tr>\n            <tr><td>Equipment</td><td>Equipment name</td></tr>\n            <tr><td>Decision</td><td>Passed/Failed/Pending</td></tr>\n            <tr><td>Checked By</td><td>Quality Controller name</td></tr>\n            <tr><td>Date</td><td>Date of quality check</td></tr>\n        </tbody>\n    </table>\n\n    <div class=\"alert alert-success\">\n        <strong>📊 Tip:</strong> Use reports to track quality trends and identify areas for improvement.\n    </div>',0,'chart-bar',1,NULL,1,'2026-06-23 15:05:02','2026-06-23 15:05:02'),(29,'Generating Certificates','generating-certificates','certificates',1,'<h2>Generating Certificates</h2>\n\n        <h3>Prerequisites</h3>\n        <ul>\n            <li>Calibration must be in <strong>\"Completed\"</strong> status</li>\n            <li>All test results must be recorded</li>\n            <li>Test results must have uncertainty calculations</li>\n        </ul>\n\n        <h3>Steps</h3>\n        <ol>\n            <li>Open the calibration details</li>\n            <li>Click <strong>Generate Certificate</strong></li>\n            <li>The certificate is created automatically with:\n                <ul>\n                    <li>Test results</li>\n                    <li>Uncertainty calculations</li>\n                    <li>Environmental conditions</li>\n                    <li>Traceability information</li>\n                </ul>\n            </li>\n            <li>You will be redirected to the certificate view</li>\n        </ol>','<h2>Generating Certificates</h2>\n\n        <h3>Prerequisites</h3>\n        <ul>\n            <li>Calibration must be in <strong>\"Completed\"</strong> status</li>\n            <li>All test results must be recorded</li>\n            <li>Test results must have uncertainty calculations</li>\n        </ul>\n\n        <h3>Steps</h3>\n        <ol>\n            <li>Open the calibration details</li>\n            <li>Click <strong>Generate Certificate</strong></li>\n            <li>The certificate is created automatically with:\n                <ul>\n                    <li>Test results</li>\n                    <li>Uncertainty calculations</li>\n                    <li>Environmental conditions</li>\n                    <li>Traceability information</li>\n                </ul>\n            </li>\n            <li>You will be redirected to the certificate view</li>\n        </ol>',0,'file-pdf',1,NULL,1,'2026-06-23 15:05:02','2026-06-23 15:05:02'),(30,'Certificate Workflow','certificate-workflow','certificates',2,'<h2>Certificate Workflow</h2>\n\n        <div class=\"bg-light p-3 rounded text-center\">\n            <p>Technician Generates Certificate</p>\n            <p>↓</p>\n            <p>Upload Test Report (from machine)</p>\n            <p>↓</p>\n            <p>Supervisor Checks & Signs</p>\n            <p>↓</p>\n            <p>Lab Manager Approves & Signs</p>\n            <p>↓</p>\n            <p>Send to Customer</p>\n        </div>\n\n        <h3>Certificate Status</h3>\n        <table>\n            <thead><tr><th>Status</th><th>Description</th><th>Action</th></tr></thead>\n            <tbody>\n                <tr><td>Generated</td><td>Certificate created</td><td>Supervisor to check</td></tr>\n                <tr><td>Checked</td><td>Supervisor reviewed</td><td>Lab Manager to approve</td></tr>\n                <tr><td>Approved</td><td>Lab Manager approved</td><td>Send to customer</td></tr>\n                <tr><td>Sent</td><td>Sent to customer</td><td>Complete</td></tr>\n            </tbody>\n        </table>','<h2>Certificate Workflow</h2>\n\n        <div class=\"bg-light p-3 rounded text-center\">\n            <p>Technician Generates Certificate</p>\n            <p>↓</p>\n            <p>Upload Test Report (from machine)</p>\n            <p>↓</p>\n            <p>Supervisor Checks & Signs</p>\n            <p>↓</p>\n            <p>Lab Manager Approves & Signs</p>\n            <p>↓</p>\n            <p>Send to Customer</p>\n        </div>\n\n        <h3>Certificate Status</h3>\n        <table>\n            <thead><tr><th>Status</th><th>Description</th><th>Action</th></tr></thead>\n            <tbody>\n                <tr><td>Generated</td><td>Certificate created</td><td>Supervisor to check</td></tr>\n                <tr><td>Checked</td><td>Supervisor reviewed</td><td>Lab Manager to approve</td></tr>\n                <tr><td>Approved</td><td>Lab Manager approved</td><td>Send to customer</td></tr>\n                <tr><td>Sent</td><td>Sent to customer</td><td>Complete</td></tr>\n            </tbody>\n        </table>',0,'flowchart',1,NULL,1,'2026-06-23 15:05:02','2026-06-23 15:05:02'),(31,'Managing Equipment Inventory','managing-equipment','equipment',1,'<h2>Managing Equipment Inventory</h2>\n\n        <h3>Viewing Equipment</h3>\n        <p>Main Menu → Equipment</p>\n\n        <h3>Adding Equipment</h3>\n        <ol>\n            <li>Navigate to Equipment</li>\n            <li>Click <strong>Add Equipment</strong></li>\n            <li>Fill in equipment details:\n                <ul>\n                    <li>Name, Serial Number, Model</li>\n                    <li>Manufacturer, Category</li>\n                    <li>Status, Condition</li>\n                </ul>\n            </li>\n            <li>Click <strong>Save Equipment</strong></li>\n        </ol>\n\n        <h3>Equipment Status</h3>\n        <table>\n            <thead><tr><th>Status</th><th>Description</th></tr></thead>\n            <tbody>\n                <tr><td>Active</td><td>Available for use</td></tr>\n                <tr><td>In Use</td><td>Currently deployed</td></tr>\n                <tr><td>Under Repair</td><td>Being repaired</td></tr>\n                <tr><td>Calibration Due</td><td>Needs calibration</td></tr>\n                <tr><td>Retired</td><td>No longer in service</td></tr>\n            </tbody>\n        </table>','<h2>Managing Equipment Inventory</h2>\n\n        <h3>Viewing Equipment</h3>\n        <p>Main Menu → Equipment</p>\n\n        <h3>Adding Equipment</h3>\n        <ol>\n            <li>Navigate to Equipment</li>\n            <li>Click <strong>Add Equipment</strong></li>\n            <li>Fill in equipment details:\n                <ul>\n                    <li>Name, Serial Number, Model</li>\n                    <li>Manufacturer, Category</li>\n                    <li>Status, Condition</li>\n                </ul>\n            </li>\n            <li>Click <strong>Save Equipment</strong></li>\n        </ol>\n\n        <h3>Equipment Status</h3>\n        <table>\n            <thead><tr><th>Status</th><th>Description</th></tr></thead>\n            <tbody>\n                <tr><td>Active</td><td>Available for use</td></tr>\n                <tr><td>In Use</td><td>Currently deployed</td></tr>\n                <tr><td>Under Repair</td><td>Being repaired</td></tr>\n                <tr><td>Calibration Due</td><td>Needs calibration</td></tr>\n                <tr><td>Retired</td><td>No longer in service</td></tr>\n            </tbody>\n        </table>',0,'tools',1,NULL,1,'2026-06-23 15:05:02','2026-06-23 15:05:02'),(42,'Laboratory Configuration Overview','laboratory-configuration-overview','laboratory-configuration',1,'<h2>Laboratory Configuration Overview</h2>\r\n\r\n<p>\r\nThe <strong>Laboratory Configuration Module</strong> is the master-data area of the\r\nKPLC Meter Calibration Laboratory System. It is used to maintain standardized\r\nrecords that are reused throughout equipment registration, calibration requests,\r\nquotations, job cards, certificates and reports.\r\n</p>\r\n\r\n<h3>Configuration Areas</h3>\r\n<ul>\r\n    <li><strong>Laboratory Services</strong> – service codes, names, methods, notes and publication status.</li>\r\n    <li><strong>Equipment Types and Pricing</strong> – equipment type names and approved laboratory rates.</li>\r\n    <li><strong>Equipment Categories</strong> – controlled equipment classification groups.</li>\r\n    <li><strong>Equipment Manufacturers</strong> – approved manufacturers and contact details.</li>\r\n    <li><strong>Audit Trail</strong> – traceability of configuration changes.</li>\r\n</ul>\r\n\r\n<h3>Opening the Module</h3>\r\n<ol>\r\n    <li>Sign in to the system.</li>\r\n    <li>Open the <strong>More</strong> menu on the top navigation bar.</li>\r\n    <li>Select <strong>Configuration</strong>.</li>\r\n</ol>\r\n\r\n<div class=\"alert alert-info\">\r\n    <i class=\"fas fa-info-circle\"></i>\r\n    The buttons shown on the Configuration dashboard depend on the permissions\r\n    assigned to the current user.\r\n</div>\r\n\r\n<h3>Dashboard Information</h3>\r\n<p>The dashboard shows summary cards for:</p>\r\n<ul>\r\n    <li>Total laboratory services and active services.</li>\r\n    <li>Total equipment pricing records.</li>\r\n    <li>Total equipment categories.</li>\r\n    <li>Total equipment manufacturers.</li>\r\n    <li>Recently updated services and pricing records.</li>\r\n    <li>Equipment records with incomplete configuration, where applicable.</li>\r\n</ul>','<h2>Laboratory Configuration Overview</h2>\r\n\r\n<p>\r\nThe <strong>Laboratory Configuration Module</strong> is the master-data area of the\r\nKPLC Meter Calibration Laboratory System. It is used to maintain standardized\r\nrecords that are reused throughout equipment registration, calibration requests,\r\nquotations, job cards, certificates and reports.\r\n</p>\r\n\r\n<h3>Configuration Areas</h3>\r\n<ul>\r\n    <li><strong>Laboratory Services</strong> – service codes, names, methods, notes and publication status.</li>\r\n    <li><strong>Equipment Types and Pricing</strong> – equipment type names and approved laboratory rates.</li>\r\n    <li><strong>Equipment Categories</strong> – controlled equipment classification groups.</li>\r\n    <li><strong>Equipment Manufacturers</strong> – approved manufacturers and contact details.</li>\r\n    <li><strong>Audit Trail</strong> – traceability of configuration changes.</li>\r\n</ul>\r\n\r\n<h3>Opening the Module</h3>\r\n<ol>\r\n    <li>Sign in to the system.</li>\r\n    <li>Open the <strong>More</strong> menu on the top navigation bar.</li>\r\n    <li>Select <strong>Configuration</strong>.</li>\r\n</ol>\r\n\r\n<div class=\"alert alert-info\">\r\n    <i class=\"fas fa-info-circle\"></i>\r\n    The buttons shown on the Configuration dashboard depend on the permissions\r\n    assigned to the current user.\r\n</div>\r\n\r\n<h3>Dashboard Information</h3>\r\n<p>The dashboard shows summary cards for:</p>\r\n<ul>\r\n    <li>Total laboratory services and active services.</li>\r\n    <li>Total equipment pricing records.</li>\r\n    <li>Total equipment categories.</li>\r\n    <li>Total equipment manufacturers.</li>\r\n    <li>Recently updated services and pricing records.</li>\r\n    <li>Equipment records with incomplete configuration, where applicable.</li>\r\n</ul>',1,'cogs',1,'{\"module\": \"Laboratory Configuration\", \"section\": \"laboratory-configuration-overview\", \"version\": \"1.0\", \"audience\": \"All authorized laboratory users\"}',1,'2026-08-03 00:29:15','2026-08-03 00:30:55'),(43,'Managing Equipment Types and Pricing','managing-equipment-types-and-pricing','laboratory-configuration',2,'<h2>Managing Equipment Types and Pricing</h2>\r\n\r\n<p>\r\nEquipment Types and Pricing define the equipment classifications used for\r\nlaboratory charges. Each record contains an equipment type name and an approved\r\nrate.\r\n</p>\r\n\r\n<h3>Viewing Pricing Records</h3>\r\n<ol>\r\n    <li>Open <strong>Configuration</strong>.</li>\r\n    <li>Select <strong>View Pricing</strong>.</li>\r\n    <li>Use the search box to find an equipment type by name or rate.</li>\r\n</ol>\r\n\r\n<h3>Creating an Equipment Type</h3>\r\n<ol>\r\n    <li>Click <strong>Add Equipment Type</strong>.</li>\r\n    <li>Enter the equipment type name.</li>\r\n    <li>Enter the published laboratory rate in Kenya shillings.</li>\r\n    <li>Confirm that the rate is approved.</li>\r\n    <li>Click <strong>Save Equipment Type</strong>.</li>\r\n</ol>\r\n\r\n<table>\r\n    <thead>\r\n        <tr><th>Field</th><th>Description</th><th>Example</th></tr>\r\n    </thead>\r\n    <tbody>\r\n        <tr><td>Equipment Type Name</td><td>Unique customer-facing equipment type</td><td>Energy Meter</td></tr>\r\n        <tr><td>Published Rate</td><td>Base calibration or testing charge</td><td>KES 3,500.00</td></tr>\r\n    </tbody>\r\n</table>\r\n\r\n<h3>Editing Pricing</h3>\r\n<ol>\r\n    <li>Locate the required equipment type.</li>\r\n    <li>Click <strong>Edit</strong>.</li>\r\n    <li>Update the name or rate.</li>\r\n    <li>Click <strong>Update Equipment Type</strong>.</li>\r\n</ol>\r\n\r\n<div class=\"alert alert-warning\">\r\n    <i class=\"fas fa-triangle-exclamation\"></i>\r\n    Updating a rate affects future use of that equipment type. Existing documents\r\n    should retain the amounts already saved on them.\r\n</div>\r\n\r\n<h3>Deleting a Pricing Record</h3>\r\n<p>\r\nA pricing record should only be deleted when it is not referenced by calibration\r\nor equipment records. Where deletion is restricted, retain the record and seek\r\nguidance from the Laboratory Manager or System Administrator.\r\n</p>','<h2>Managing Equipment Types and Pricing</h2>\r\n\r\n<p>\r\nEquipment Types and Pricing define the equipment classifications used for\r\nlaboratory charges. Each record contains an equipment type name and an approved\r\nrate.\r\n</p>\r\n\r\n<h3>Viewing Pricing Records</h3>\r\n<ol>\r\n    <li>Open <strong>Configuration</strong>.</li>\r\n    <li>Select <strong>View Pricing</strong>.</li>\r\n    <li>Use the search box to find an equipment type by name or rate.</li>\r\n</ol>\r\n\r\n<h3>Creating an Equipment Type</h3>\r\n<ol>\r\n    <li>Click <strong>Add Equipment Type</strong>.</li>\r\n    <li>Enter the equipment type name.</li>\r\n    <li>Enter the published laboratory rate in Kenya shillings.</li>\r\n    <li>Confirm that the rate is approved.</li>\r\n    <li>Click <strong>Save Equipment Type</strong>.</li>\r\n</ol>\r\n\r\n<table>\r\n    <thead>\r\n        <tr><th>Field</th><th>Description</th><th>Example</th></tr>\r\n    </thead>\r\n    <tbody>\r\n        <tr><td>Equipment Type Name</td><td>Unique customer-facing equipment type</td><td>Energy Meter</td></tr>\r\n        <tr><td>Published Rate</td><td>Base calibration or testing charge</td><td>KES 3,500.00</td></tr>\r\n    </tbody>\r\n</table>\r\n\r\n<h3>Editing Pricing</h3>\r\n<ol>\r\n    <li>Locate the required equipment type.</li>\r\n    <li>Click <strong>Edit</strong>.</li>\r\n    <li>Update the name or rate.</li>\r\n    <li>Click <strong>Update Equipment Type</strong>.</li>\r\n</ol>\r\n\r\n<div class=\"alert alert-warning\">\r\n    <i class=\"fas fa-triangle-exclamation\"></i>\r\n    Updating a rate affects future use of that equipment type. Existing documents\r\n    should retain the amounts already saved on them.\r\n</div>\r\n\r\n<h3>Deleting a Pricing Record</h3>\r\n<p>\r\nA pricing record should only be deleted when it is not referenced by calibration\r\nor equipment records. Where deletion is restricted, retain the record and seek\r\nguidance from the Laboratory Manager or System Administrator.\r\n</p>',1,'tags',1,'{\"module\": \"Laboratory Configuration\", \"section\": \"managing-equipment-types-and-pricing\", \"version\": \"1.0\", \"audience\": \"Lab Manager, Supervisor, Super Admin; Lab Technician view only\"}',1,'2026-08-03 00:29:15','2026-08-03 00:31:55'),(44,'Managing Laboratory Service Types','managing-laboratory-service-types','laboratory-configuration',3,'<h2>Managing Laboratory Service Types</h2>\r\n\r\n<p>\r\nLaboratory Service Types describe the services offered by the laboratory. A\r\nservice record contains a service code, service name, applicable method,\r\npublic notes, internal comments and an active or inactive status.\r\n</p>\r\n\r\n<h3>Creating a Service</h3>\r\n<ol>\r\n    <li>Open <strong>Configuration</strong>.</li>\r\n    <li>Select <strong>Add Service</strong>.</li>\r\n    <li>Complete the required fields.</li>\r\n    <li>Set the publication status.</li>\r\n    <li>Click <strong>Save Laboratory Service</strong>.</li>\r\n</ol>\r\n\r\n<table>\r\n    <thead>\r\n        <tr><th>Field</th><th>Description</th><th>Example</th></tr>\r\n    </thead>\r\n    <tbody>\r\n        <tr><td>Service Code</td><td>Unique short code</td><td>CAL</td></tr>\r\n        <tr><td>Service Name</td><td>Customer-facing service name</td><td>Energy Meter Calibration</td></tr>\r\n        <tr><td>Method / Standard</td><td>Applicable procedure or standard</td><td>IEC 62053</td></tr>\r\n        <tr><td>Public Notes</td><td>Information that may be shown publicly</td><td>Standard laboratory calibration service</td></tr>\r\n        <tr><td>Internal Comments</td><td>Remarks for laboratory staff</td><td>Use approved bench procedure</td></tr>\r\n        <tr><td>Status</td><td>Controls public and operational availability</td><td>Active</td></tr>\r\n    </tbody>\r\n</table>\r\n\r\n<h3>Active and Inactive Services</h3>\r\n<ul>\r\n    <li><strong>Active:</strong> available for use and may appear in public or operational service lists.</li>\r\n    <li><strong>Inactive:</strong> hidden from new selections while historical records remain available.</li>\r\n</ul>\r\n\r\n<h3>Editing a Service</h3>\r\n<ol>\r\n    <li>Open the service catalogue.</li>\r\n    <li>Click <strong>Edit</strong> beside the required service.</li>\r\n    <li>Update the details.</li>\r\n    <li>Click <strong>Update Laboratory Service</strong>.</li>\r\n</ol>\r\n\r\n<div class=\"alert alert-success\">\r\n    <i class=\"fas fa-check-circle\"></i>\r\n    Deactivate a service instead of deleting it when the service has already\r\n    been used in system records.\r\n</div>','<h2>Managing Laboratory Service Types</h2>\r\n\r\n<p>\r\nLaboratory Service Types describe the services offered by the laboratory. A\r\nservice record contains a service code, service name, applicable method,\r\npublic notes, internal comments and an active or inactive status.\r\n</p>\r\n\r\n<h3>Creating a Service</h3>\r\n<ol>\r\n    <li>Open <strong>Configuration</strong>.</li>\r\n    <li>Select <strong>Add Service</strong>.</li>\r\n    <li>Complete the required fields.</li>\r\n    <li>Set the publication status.</li>\r\n    <li>Click <strong>Save Laboratory Service</strong>.</li>\r\n</ol>\r\n\r\n<table>\r\n    <thead>\r\n        <tr><th>Field</th><th>Description</th><th>Example</th></tr>\r\n    </thead>\r\n    <tbody>\r\n        <tr><td>Service Code</td><td>Unique short code</td><td>CAL</td></tr>\r\n        <tr><td>Service Name</td><td>Customer-facing service name</td><td>Energy Meter Calibration</td></tr>\r\n        <tr><td>Method / Standard</td><td>Applicable procedure or standard</td><td>IEC 62053</td></tr>\r\n        <tr><td>Public Notes</td><td>Information that may be shown publicly</td><td>Standard laboratory calibration service</td></tr>\r\n        <tr><td>Internal Comments</td><td>Remarks for laboratory staff</td><td>Use approved bench procedure</td></tr>\r\n        <tr><td>Status</td><td>Controls public and operational availability</td><td>Active</td></tr>\r\n    </tbody>\r\n</table>\r\n\r\n<h3>Active and Inactive Services</h3>\r\n<ul>\r\n    <li><strong>Active:</strong> available for use and may appear in public or operational service lists.</li>\r\n    <li><strong>Inactive:</strong> hidden from new selections while historical records remain available.</li>\r\n</ul>\r\n\r\n<h3>Editing a Service</h3>\r\n<ol>\r\n    <li>Open the service catalogue.</li>\r\n    <li>Click <strong>Edit</strong> beside the required service.</li>\r\n    <li>Update the details.</li>\r\n    <li>Click <strong>Update Laboratory Service</strong>.</li>\r\n</ol>\r\n\r\n<div class=\"alert alert-success\">\r\n    <i class=\"fas fa-check-circle\"></i>\r\n    Deactivate a service instead of deleting it when the service has already\r\n    been used in system records.\r\n</div>',0,'flask-vial',1,'{\"module\": \"Laboratory Configuration\", \"section\": \"managing-laboratory-service-types\", \"version\": \"1.0\", \"audience\": \"Lab Manager, Supervisor, Super Admin; Lab Technician view only\"}',1,'2026-08-03 00:29:15','2026-08-03 00:29:15'),(45,'Managing Equipment Categories','managing-equipment-categories','laboratory-configuration',4,'<h2>Managing Equipment Categories</h2>\r\n\r\n<p>\r\nEquipment Categories are controlled classification groups used when registering\r\nand organizing equipment.\r\n</p>\r\n\r\n<h3>Creating a Category</h3>\r\n<ol>\r\n    <li>Open <strong>Configuration</strong>.</li>\r\n    <li>Select <strong>Add Category</strong>.</li>\r\n    <li>Enter a unique category name and code.</li>\r\n    <li>Add a clear description.</li>\r\n    <li>Set the category status.</li>\r\n    <li>Click <strong>Save Equipment Category</strong>.</li>\r\n</ol>\r\n\r\n<table>\r\n    <thead>\r\n        <tr><th>Field</th><th>Description</th><th>Example</th></tr>\r\n    </thead>\r\n    <tbody>\r\n        <tr><td>Category Name</td><td>Classification name</td><td>Reference Standards</td></tr>\r\n        <tr><td>Category Code</td><td>Unique code using letters, numbers, hyphens or underscores</td><td>REF_STD</td></tr>\r\n        <tr><td>Description</td><td>Equipment included in the category</td><td>Standards used for traceability and comparison</td></tr>\r\n        <tr><td>Status</td><td>Availability during equipment registration</td><td>Active</td></tr>\r\n    </tbody>\r\n</table>\r\n\r\n<h3>Editing a Category</h3>\r\n<ol>\r\n    <li>Open the category list.</li>\r\n    <li>Click <strong>Edit</strong>.</li>\r\n    <li>Update the required information.</li>\r\n    <li>Click <strong>Update Equipment Category</strong>.</li>\r\n</ol>\r\n\r\n<h3>Deletion Rules</h3>\r\n<p>\r\nA category assigned to equipment cannot be deleted. Deactivate the category\r\ninstead so that it is no longer available for new registrations.\r\n</p>\r\n\r\n<div class=\"alert alert-warning\">\r\n    <i class=\"fas fa-triangle-exclamation\"></i>\r\n    Changing a category code or name may affect how equipment is identified in\r\n    searches and reports. Use consistent naming conventions.\r\n</div>','<h2>Managing Equipment Categories</h2>\r\n\r\n<p>\r\nEquipment Categories are controlled classification groups used when registering\r\nand organizing equipment.\r\n</p>\r\n\r\n<h3>Creating a Category</h3>\r\n<ol>\r\n    <li>Open <strong>Configuration</strong>.</li>\r\n    <li>Select <strong>Add Category</strong>.</li>\r\n    <li>Enter a unique category name and code.</li>\r\n    <li>Add a clear description.</li>\r\n    <li>Set the category status.</li>\r\n    <li>Click <strong>Save Equipment Category</strong>.</li>\r\n</ol>\r\n\r\n<table>\r\n    <thead>\r\n        <tr><th>Field</th><th>Description</th><th>Example</th></tr>\r\n    </thead>\r\n    <tbody>\r\n        <tr><td>Category Name</td><td>Classification name</td><td>Reference Standards</td></tr>\r\n        <tr><td>Category Code</td><td>Unique code using letters, numbers, hyphens or underscores</td><td>REF_STD</td></tr>\r\n        <tr><td>Description</td><td>Equipment included in the category</td><td>Standards used for traceability and comparison</td></tr>\r\n        <tr><td>Status</td><td>Availability during equipment registration</td><td>Active</td></tr>\r\n    </tbody>\r\n</table>\r\n\r\n<h3>Editing a Category</h3>\r\n<ol>\r\n    <li>Open the category list.</li>\r\n    <li>Click <strong>Edit</strong>.</li>\r\n    <li>Update the required information.</li>\r\n    <li>Click <strong>Update Equipment Category</strong>.</li>\r\n</ol>\r\n\r\n<h3>Deletion Rules</h3>\r\n<p>\r\nA category assigned to equipment cannot be deleted. Deactivate the category\r\ninstead so that it is no longer available for new registrations.\r\n</p>\r\n\r\n<div class=\"alert alert-warning\">\r\n    <i class=\"fas fa-triangle-exclamation\"></i>\r\n    Changing a category code or name may affect how equipment is identified in\r\n    searches and reports. Use consistent naming conventions.\r\n</div>',0,'layer-group',1,'{\"module\": \"Laboratory Configuration\", \"section\": \"managing-equipment-categories\", \"version\": \"1.0\", \"audience\": \"Lab Manager, Supervisor, Super Admin; Lab Technician view only\"}',1,'2026-08-03 00:29:15','2026-08-03 00:29:15'),(46,'Managing Equipment Manufacturers','managing-equipment-manufacturers','laboratory-configuration',5,'<h2>Managing Equipment Manufacturers</h2>\r\n\r\n<p>\r\nEquipment Manufacturers store approved manufacturer identification and contact\r\ndetails used during equipment registration.\r\n</p>\r\n\r\n<h3>Creating a Manufacturer</h3>\r\n<ol>\r\n    <li>Open <strong>Configuration</strong>.</li>\r\n    <li>Select <strong>Add Manufacturer</strong>.</li>\r\n    <li>Enter the manufacturer name and unique code.</li>\r\n    <li>Add the website and available contact details.</li>\r\n    <li>Set the status.</li>\r\n    <li>Click <strong>Save Manufacturer</strong>.</li>\r\n</ol>\r\n\r\n<table>\r\n    <thead>\r\n        <tr><th>Field</th><th>Description</th><th>Example</th></tr>\r\n    </thead>\r\n    <tbody>\r\n        <tr><td>Manufacturer Name</td><td>Approved manufacturer or supplier name</td><td>Landis+Gyr</td></tr>\r\n        <tr><td>Manufacturer Code</td><td>Unique short code</td><td>LANDIS</td></tr>\r\n        <tr><td>Website</td><td>Full web address</td><td>https://www.example.com</td></tr>\r\n        <tr><td>Contact Person</td><td>Primary contact name</td><td>Jane Doe</td></tr>\r\n        <tr><td>Contact Phone</td><td>Contact telephone number</td><td>+254...</td></tr>\r\n        <tr><td>Contact Email</td><td>Valid email address</td><td>contact@example.com</td></tr>\r\n        <tr><td>Address</td><td>Physical or postal address</td><td>Nairobi, Kenya</td></tr>\r\n        <tr><td>Status</td><td>Availability during equipment registration</td><td>Active</td></tr>\r\n    </tbody>\r\n</table>\r\n\r\n<h3>Editing and Deactivating</h3>\r\n<p>\r\nUse <strong>Edit</strong> to update manufacturer details. Deactivate a\r\nmanufacturer when it should not be selected for new equipment but must remain\r\navailable for historical records.\r\n</p>\r\n\r\n<h3>Deletion Rules</h3>\r\n<p>\r\nA manufacturer linked to equipment cannot be deleted. The system will require\r\nthe record to be deactivated instead.\r\n</p>','<h2>Managing Equipment Manufacturers</h2>\r\n\r\n<p>\r\nEquipment Manufacturers store approved manufacturer identification and contact\r\ndetails used during equipment registration.\r\n</p>\r\n\r\n<h3>Creating a Manufacturer</h3>\r\n<ol>\r\n    <li>Open <strong>Configuration</strong>.</li>\r\n    <li>Select <strong>Add Manufacturer</strong>.</li>\r\n    <li>Enter the manufacturer name and unique code.</li>\r\n    <li>Add the website and available contact details.</li>\r\n    <li>Set the status.</li>\r\n    <li>Click <strong>Save Manufacturer</strong>.</li>\r\n</ol>\r\n\r\n<table>\r\n    <thead>\r\n        <tr><th>Field</th><th>Description</th><th>Example</th></tr>\r\n    </thead>\r\n    <tbody>\r\n        <tr><td>Manufacturer Name</td><td>Approved manufacturer or supplier name</td><td>Landis+Gyr</td></tr>\r\n        <tr><td>Manufacturer Code</td><td>Unique short code</td><td>LANDIS</td></tr>\r\n        <tr><td>Website</td><td>Full web address</td><td>https://www.example.com</td></tr>\r\n        <tr><td>Contact Person</td><td>Primary contact name</td><td>Jane Doe</td></tr>\r\n        <tr><td>Contact Phone</td><td>Contact telephone number</td><td>+254...</td></tr>\r\n        <tr><td>Contact Email</td><td>Valid email address</td><td>contact@example.com</td></tr>\r\n        <tr><td>Address</td><td>Physical or postal address</td><td>Nairobi, Kenya</td></tr>\r\n        <tr><td>Status</td><td>Availability during equipment registration</td><td>Active</td></tr>\r\n    </tbody>\r\n</table>\r\n\r\n<h3>Editing and Deactivating</h3>\r\n<p>\r\nUse <strong>Edit</strong> to update manufacturer details. Deactivate a\r\nmanufacturer when it should not be selected for new equipment but must remain\r\navailable for historical records.\r\n</p>\r\n\r\n<h3>Deletion Rules</h3>\r\n<p>\r\nA manufacturer linked to equipment cannot be deleted. The system will require\r\nthe record to be deactivated instead.\r\n</p>',0,'industry',1,'{\"module\": \"Laboratory Configuration\", \"section\": \"managing-equipment-manufacturers\", \"version\": \"1.0\", \"audience\": \"Lab Manager, Supervisor, Super Admin; Lab Technician view only\"}',1,'2026-08-03 00:29:15','2026-08-03 00:29:15'),(47,'Equipment Registration and Configuration Integration','equipment-registration-configuration-integration','laboratory-configuration',6,'<h2>Equipment Registration and Configuration Integration</h2>\r\n\r\n<p>\r\nThe Equipment module uses controlled values from Laboratory Configuration.\r\nThis reduces duplicate names and ensures consistent reporting.\r\n</p>\r\n\r\n<h3>Configuration Fields on Equipment</h3>\r\n<ul>\r\n    <li><strong>Equipment Category</strong> – selected from active equipment categories.</li>\r\n    <li><strong>Manufacturer</strong> – selected from active approved manufacturers.</li>\r\n    <li><strong>Equipment Type / Pricing Category</strong> – selected from the equipment type pricing list.</li>\r\n    <li><strong>Published Base Rate</strong> – displayed from the selected equipment type.</li>\r\n</ul>\r\n\r\n<h3>Creating Equipment</h3>\r\n<ol>\r\n    <li>Open <strong>Equipment</strong>.</li>\r\n    <li>Click <strong>Add Equipment</strong>.</li>\r\n    <li>Enter the equipment name, serial number and model.</li>\r\n    <li>Select the configured category, manufacturer and equipment type.</li>\r\n    <li>Confirm status and condition.</li>\r\n    <li>Click <strong>Save Equipment</strong>.</li>\r\n</ol>\r\n\r\n<h3>Editing Existing Equipment</h3>\r\n<p>\r\nWhen editing an older record, an inactive category or manufacturer may still\r\nappear with the label <strong>Inactive – Current Selection</strong>. This allows\r\nthe existing record to remain valid until a replacement selection is made.\r\n</p>\r\n\r\n<h3>Configuration Completeness</h3>\r\n<p>\r\nEquipment is considered fully configured when category, manufacturer and\r\nequipment type are all assigned.\r\n</p>\r\n\r\n<div class=\"alert alert-warning\">\r\n    <i class=\"fas fa-triangle-exclamation\"></i>\r\n    Equipment marked as configuration incomplete should be reviewed and updated\r\n    through the Equipment edit page.\r\n</div>','<h2>Equipment Registration and Configuration Integration</h2>\r\n\r\n<p>\r\nThe Equipment module uses controlled values from Laboratory Configuration.\r\nThis reduces duplicate names and ensures consistent reporting.\r\n</p>\r\n\r\n<h3>Configuration Fields on Equipment</h3>\r\n<ul>\r\n    <li><strong>Equipment Category</strong> – selected from active equipment categories.</li>\r\n    <li><strong>Manufacturer</strong> – selected from active approved manufacturers.</li>\r\n    <li><strong>Equipment Type / Pricing Category</strong> – selected from the equipment type pricing list.</li>\r\n    <li><strong>Published Base Rate</strong> – displayed from the selected equipment type.</li>\r\n</ul>\r\n\r\n<h3>Creating Equipment</h3>\r\n<ol>\r\n    <li>Open <strong>Equipment</strong>.</li>\r\n    <li>Click <strong>Add Equipment</strong>.</li>\r\n    <li>Enter the equipment name, serial number and model.</li>\r\n    <li>Select the configured category, manufacturer and equipment type.</li>\r\n    <li>Confirm status and condition.</li>\r\n    <li>Click <strong>Save Equipment</strong>.</li>\r\n</ol>\r\n\r\n<h3>Editing Existing Equipment</h3>\r\n<p>\r\nWhen editing an older record, an inactive category or manufacturer may still\r\nappear with the label <strong>Inactive – Current Selection</strong>. This allows\r\nthe existing record to remain valid until a replacement selection is made.\r\n</p>\r\n\r\n<h3>Configuration Completeness</h3>\r\n<p>\r\nEquipment is considered fully configured when category, manufacturer and\r\nequipment type are all assigned.\r\n</p>\r\n\r\n<div class=\"alert alert-warning\">\r\n    <i class=\"fas fa-triangle-exclamation\"></i>\r\n    Equipment marked as configuration incomplete should be reviewed and updated\r\n    through the Equipment edit page.\r\n</div>',1,'tools',1,'{\"module\": \"Laboratory Configuration\", \"section\": \"equipment-registration-configuration-integration\", \"version\": \"1.0\", \"audience\": \"Users who create or edit equipment\"}',1,'2026-08-03 00:29:15','2026-08-03 00:31:39'),(48,'Configuration Permissions and Role Access','configuration-permissions-and-role-access','laboratory-configuration',7,'<h2>Configuration Permissions and Role Access</h2>\r\n\r\n<p>\r\nAccess is controlled using role-based permissions. The exact buttons displayed\r\ndepend on the permissions assigned to the logged-in user.\r\n</p>\r\n\r\n<table>\r\n    <thead>\r\n        <tr>\r\n            <th>Activity</th>\r\n            <th>Super Admin</th>\r\n            <th>Lab Manager</th>\r\n            <th>Supervisor</th>\r\n            <th>Lab Technician</th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n        <tr><td>View Configuration dashboard</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td></tr>\r\n        <tr><td>View services, pricing, categories and manufacturers</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td></tr>\r\n        <tr><td>Create configuration records</td><td>Yes</td><td>Yes</td><td>Subject to assigned permissions</td><td>No</td></tr>\r\n        <tr><td>Edit configuration records</td><td>Yes</td><td>Yes</td><td>Subject to assigned permissions</td><td>No</td></tr>\r\n        <tr><td>Delete configuration records</td><td>Yes</td><td>Subject to assigned permissions</td><td>Normally No</td><td>No</td></tr>\r\n        <tr><td>View configuration audit trail</td><td>Yes</td><td>Yes</td><td>Subject to assigned permissions</td><td>No unless granted</td></tr>\r\n    </tbody>\r\n</table>\r\n\r\n<h3>Read-Only Access</h3>\r\n<p>\r\nA Lab Technician with the view permissions can open the Configuration dashboard\r\nand view records. Create, edit, toggle-status and delete buttons remain hidden.\r\n</p>\r\n\r\n<h3>Access Denied Message</h3>\r\n<p>\r\nIf the system displays <strong>User does not have the right permissions</strong>,\r\nthe requested route requires a permission that is not assigned to the user or\r\ntheir role.\r\n</p>\r\n\r\n<div class=\"alert alert-info\">\r\n    <i class=\"fas fa-info-circle\"></i>\r\n    Contact the Laboratory Manager or System Administrator when access appears\r\n    inconsistent with assigned duties.\r\n</div>','<h2>Configuration Permissions and Role Access</h2>\r\n\r\n<p>\r\nAccess is controlled using role-based permissions. The exact buttons displayed\r\ndepend on the permissions assigned to the logged-in user.\r\n</p>\r\n\r\n<table>\r\n    <thead>\r\n        <tr>\r\n            <th>Activity</th>\r\n            <th>Super Admin</th>\r\n            <th>Lab Manager</th>\r\n            <th>Supervisor</th>\r\n            <th>Lab Technician</th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n        <tr><td>View Configuration dashboard</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td></tr>\r\n        <tr><td>View services, pricing, categories and manufacturers</td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td></tr>\r\n        <tr><td>Create configuration records</td><td>Yes</td><td>Yes</td><td>Subject to assigned permissions</td><td>No</td></tr>\r\n        <tr><td>Edit configuration records</td><td>Yes</td><td>Yes</td><td>Subject to assigned permissions</td><td>No</td></tr>\r\n        <tr><td>Delete configuration records</td><td>Yes</td><td>Subject to assigned permissions</td><td>Normally No</td><td>No</td></tr>\r\n        <tr><td>View configuration audit trail</td><td>Yes</td><td>Yes</td><td>Subject to assigned permissions</td><td>No unless granted</td></tr>\r\n    </tbody>\r\n</table>\r\n\r\n<h3>Read-Only Access</h3>\r\n<p>\r\nA Lab Technician with the view permissions can open the Configuration dashboard\r\nand view records. Create, edit, toggle-status and delete buttons remain hidden.\r\n</p>\r\n\r\n<h3>Access Denied Message</h3>\r\n<p>\r\nIf the system displays <strong>User does not have the right permissions</strong>,\r\nthe requested route requires a permission that is not assigned to the user or\r\ntheir role.\r\n</p>\r\n\r\n<div class=\"alert alert-info\">\r\n    <i class=\"fas fa-info-circle\"></i>\r\n    Contact the Laboratory Manager or System Administrator when access appears\r\n    inconsistent with assigned duties.\r\n</div>',0,'user-shield',1,'{\"module\": \"Laboratory Configuration\", \"section\": \"configuration-permissions-and-role-access\", \"version\": \"1.0\", \"audience\": \"All users and system administrators\"}',1,'2026-08-03 00:29:15','2026-08-03 00:29:15'),(49,'Configuration Audit Trail','configuration-audit-trail','laboratory-configuration',8,'<h2>Configuration Audit Trail</h2>\r\n\r\n<p>\r\nThe Configuration Audit Trail records changes made to laboratory services,\r\nequipment pricing, categories and manufacturers.\r\n</p>\r\n\r\n<h3>Opening the Audit Trail</h3>\r\n<ol>\r\n    <li>Open <strong>Configuration</strong>.</li>\r\n    <li>Click <strong>Audit Trail</strong>.</li>\r\n</ol>\r\n\r\n<h3>Information Recorded</h3>\r\n<ul>\r\n    <li>Date and time.</li>\r\n    <li>User who performed the action.</li>\r\n    <li>Action performed.</li>\r\n    <li>Description of the change.</li>\r\n    <li>Old values.</li>\r\n    <li>New values.</li>\r\n    <li>IP address.</li>\r\n</ul>\r\n\r\n<h3>Searching and Filtering</h3>\r\n<p>\r\nUse the search box to find activities by description or user. Use the action\r\nfilter to display a specific type of activity, such as creation, update,\r\nactivation, deactivation or deletion.\r\n</p>\r\n\r\n<h3>Reviewing Changes</h3>\r\n<p>\r\nWhere old and new values are available, select <strong>View changes</strong> to\r\ncompare the values before and after the update.\r\n</p>\r\n\r\n<div class=\"alert alert-warning\">\r\n    <i class=\"fas fa-triangle-exclamation\"></i>\r\n    Audit records are for traceability and should not be altered or deleted\r\n    during normal system operation.\r\n</div>','<h2>Configuration Audit Trail</h2>\r\n\r\n<p>\r\nThe Configuration Audit Trail records changes made to laboratory services,\r\nequipment pricing, categories and manufacturers.\r\n</p>\r\n\r\n<h3>Opening the Audit Trail</h3>\r\n<ol>\r\n    <li>Open <strong>Configuration</strong>.</li>\r\n    <li>Click <strong>Audit Trail</strong>.</li>\r\n</ol>\r\n\r\n<h3>Information Recorded</h3>\r\n<ul>\r\n    <li>Date and time.</li>\r\n    <li>User who performed the action.</li>\r\n    <li>Action performed.</li>\r\n    <li>Description of the change.</li>\r\n    <li>Old values.</li>\r\n    <li>New values.</li>\r\n    <li>IP address.</li>\r\n</ul>\r\n\r\n<h3>Searching and Filtering</h3>\r\n<p>\r\nUse the search box to find activities by description or user. Use the action\r\nfilter to display a specific type of activity, such as creation, update,\r\nactivation, deactivation or deletion.\r\n</p>\r\n\r\n<h3>Reviewing Changes</h3>\r\n<p>\r\nWhere old and new values are available, select <strong>View changes</strong> to\r\ncompare the values before and after the update.\r\n</p>\r\n\r\n<div class=\"alert alert-warning\">\r\n    <i class=\"fas fa-triangle-exclamation\"></i>\r\n    Audit records are for traceability and should not be altered or deleted\r\n    during normal system operation.\r\n</div>',2,'clock-rotate-left',1,'{\"module\": \"Laboratory Configuration\", \"section\": \"configuration-audit-trail\", \"version\": \"1.0\", \"audience\": \"Authorized managers, supervisors and administrators\"}',1,'2026-08-03 00:29:15','2026-08-03 00:35:41'),(50,'Laboratory Configuration Best Practices','laboratory-configuration-best-practices','laboratory-configuration',9,'<h2>Laboratory Configuration Best Practices</h2>\r\n\r\n<h3>Use Consistent Naming</h3>\r\n<ul>\r\n    <li>Use approved names for equipment types, categories and manufacturers.</li>\r\n    <li>Avoid unnecessary abbreviations.</li>\r\n    <li>Use unique, meaningful codes.</li>\r\n    <li>Check for an existing record before creating a new one.</li>\r\n</ul>\r\n\r\n<h3>Manage Status Carefully</h3>\r\n<ul>\r\n    <li>Use <strong>Inactive</strong> instead of deleting records that have already been used.</li>\r\n    <li>Activate only services and manufacturers approved for current use.</li>\r\n    <li>Review inactive records periodically.</li>\r\n</ul>\r\n\r\n<h3>Manage Pricing Carefully</h3>\r\n<ul>\r\n    <li>Confirm rates before saving.</li>\r\n    <li>Record pricing changes through an authorized user.</li>\r\n    <li>Review the audit trail after significant changes.</li>\r\n    <li>Ensure rates are entered as numeric values in Kenya shillings.</li>\r\n</ul>\r\n\r\n<h3>Protect Data Integrity</h3>\r\n<ul>\r\n    <li>Do not create duplicate categories or manufacturers.</li>\r\n    <li>Do not remove records linked to equipment.</li>\r\n    <li>Complete missing configuration for legacy equipment.</li>\r\n    <li>Use the equipment configuration completeness filter regularly.</li>\r\n</ul>\r\n\r\n<div class=\"alert alert-success\">\r\n    <i class=\"fas fa-check-circle\"></i>\r\n    Well-maintained configuration improves document accuracy, search results,\r\n    finance reporting and equipment traceability.\r\n</div>','<h2>Laboratory Configuration Best Practices</h2>\r\n\r\n<h3>Use Consistent Naming</h3>\r\n<ul>\r\n    <li>Use approved names for equipment types, categories and manufacturers.</li>\r\n    <li>Avoid unnecessary abbreviations.</li>\r\n    <li>Use unique, meaningful codes.</li>\r\n    <li>Check for an existing record before creating a new one.</li>\r\n</ul>\r\n\r\n<h3>Manage Status Carefully</h3>\r\n<ul>\r\n    <li>Use <strong>Inactive</strong> instead of deleting records that have already been used.</li>\r\n    <li>Activate only services and manufacturers approved for current use.</li>\r\n    <li>Review inactive records periodically.</li>\r\n</ul>\r\n\r\n<h3>Manage Pricing Carefully</h3>\r\n<ul>\r\n    <li>Confirm rates before saving.</li>\r\n    <li>Record pricing changes through an authorized user.</li>\r\n    <li>Review the audit trail after significant changes.</li>\r\n    <li>Ensure rates are entered as numeric values in Kenya shillings.</li>\r\n</ul>\r\n\r\n<h3>Protect Data Integrity</h3>\r\n<ul>\r\n    <li>Do not create duplicate categories or manufacturers.</li>\r\n    <li>Do not remove records linked to equipment.</li>\r\n    <li>Complete missing configuration for legacy equipment.</li>\r\n    <li>Use the equipment configuration completeness filter regularly.</li>\r\n</ul>\r\n\r\n<div class=\"alert alert-success\">\r\n    <i class=\"fas fa-check-circle\"></i>\r\n    Well-maintained configuration improves document accuracy, search results,\r\n    finance reporting and equipment traceability.\r\n</div>',0,'check-double',1,'{\"module\": \"Laboratory Configuration\", \"section\": \"laboratory-configuration-best-practices\", \"version\": \"1.0\", \"audience\": \"Configuration managers and supervisors\"}',1,'2026-08-03 00:29:15','2026-08-03 00:29:15'),(51,'Laboratory Configuration Troubleshooting and FAQ','laboratory-configuration-troubleshooting','laboratory-configuration',10,'<h2>Laboratory Configuration Troubleshooting and FAQ</h2>\r\n\r\n<table>\r\n    <thead>\r\n        <tr><th>Problem</th><th>Likely Cause</th><th>Recommended Action</th></tr>\r\n    </thead>\r\n    <tbody>\r\n        <tr>\r\n            <td>Configuration menu is not visible</td>\r\n            <td>The user lacks all configuration view permissions</td>\r\n            <td>Ask an administrator to verify the assigned Spatie role and permissions</td>\r\n        </tr>\r\n        <tr>\r\n            <td>User does not have the right permissions</td>\r\n            <td>The requested route requires a permission not assigned to the user</td>\r\n            <td>Confirm the route middleware and the user&apos;s effective permissions</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Add or Edit button is missing</td>\r\n            <td>The user has view-only access</td>\r\n            <td>Request the relevant create or edit permission where justified</td>\r\n        </tr>\r\n        <tr>\r\n            <td>A service does not appear in operational forms</td>\r\n            <td>The service is inactive</td>\r\n            <td>Open the service record and activate it if approved</td>\r\n        </tr>\r\n        <tr>\r\n            <td>A category or manufacturer cannot be deleted</td>\r\n            <td>It is already linked to equipment</td>\r\n            <td>Deactivate the record instead</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Equipment shows Configuration Incomplete</td>\r\n            <td>Category, manufacturer or pricing type is missing</td>\r\n            <td>Open the equipment edit page and complete all configuration fields</td>\r\n        </tr>\r\n        <tr>\r\n            <td>A manufacturer is missing from the equipment form</td>\r\n            <td>The manufacturer is inactive</td>\r\n            <td>Activate it or select another approved manufacturer</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Pricing rate is incorrect</td>\r\n            <td>The equipment type rate is outdated</td>\r\n            <td>Ask an authorized user to update the pricing record</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Recent changes do not appear</td>\r\n            <td>Application or permission cache may be stale</td>\r\n            <td>Clear the relevant caches and sign in again</td>\r\n        </tr>\r\n    </tbody>\r\n</table>\r\n\r\n<h3>Frequently Asked Questions</h3>\r\n\r\n<h4>Should an old configuration record be deleted?</h4>\r\n<p>\r\nNormally no. Deactivate records that are already referenced by historical\r\nequipment or calibration data.\r\n</p>\r\n\r\n<h4>Can a Lab Technician edit configuration?</h4>\r\n<p>\r\nNot with view-only permissions. A Lab Technician can review configuration\r\nrecords but cannot create, edit or delete them unless additional permissions are\r\nexplicitly granted.\r\n</p>\r\n\r\n<h4>Why does an inactive record appear during editing?</h4>\r\n<p>\r\nThe system may include the currently selected inactive record so that an\r\nexisting equipment record does not lose its saved configuration.\r\n</p>','<h2>Laboratory Configuration Troubleshooting and FAQ</h2>\r\n\r\n<table>\r\n    <thead>\r\n        <tr><th>Problem</th><th>Likely Cause</th><th>Recommended Action</th></tr>\r\n    </thead>\r\n    <tbody>\r\n        <tr>\r\n            <td>Configuration menu is not visible</td>\r\n            <td>The user lacks all configuration view permissions</td>\r\n            <td>Ask an administrator to verify the assigned Spatie role and permissions</td>\r\n        </tr>\r\n        <tr>\r\n            <td>User does not have the right permissions</td>\r\n            <td>The requested route requires a permission not assigned to the user</td>\r\n            <td>Confirm the route middleware and the user&apos;s effective permissions</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Add or Edit button is missing</td>\r\n            <td>The user has view-only access</td>\r\n            <td>Request the relevant create or edit permission where justified</td>\r\n        </tr>\r\n        <tr>\r\n            <td>A service does not appear in operational forms</td>\r\n            <td>The service is inactive</td>\r\n            <td>Open the service record and activate it if approved</td>\r\n        </tr>\r\n        <tr>\r\n            <td>A category or manufacturer cannot be deleted</td>\r\n            <td>It is already linked to equipment</td>\r\n            <td>Deactivate the record instead</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Equipment shows Configuration Incomplete</td>\r\n            <td>Category, manufacturer or pricing type is missing</td>\r\n            <td>Open the equipment edit page and complete all configuration fields</td>\r\n        </tr>\r\n        <tr>\r\n            <td>A manufacturer is missing from the equipment form</td>\r\n            <td>The manufacturer is inactive</td>\r\n            <td>Activate it or select another approved manufacturer</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Pricing rate is incorrect</td>\r\n            <td>The equipment type rate is outdated</td>\r\n            <td>Ask an authorized user to update the pricing record</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Recent changes do not appear</td>\r\n            <td>Application or permission cache may be stale</td>\r\n            <td>Clear the relevant caches and sign in again</td>\r\n        </tr>\r\n    </tbody>\r\n</table>\r\n\r\n<h3>Frequently Asked Questions</h3>\r\n\r\n<h4>Should an old configuration record be deleted?</h4>\r\n<p>\r\nNormally no. Deactivate records that are already referenced by historical\r\nequipment or calibration data.\r\n</p>\r\n\r\n<h4>Can a Lab Technician edit configuration?</h4>\r\n<p>\r\nNot with view-only permissions. A Lab Technician can review configuration\r\nrecords but cannot create, edit or delete them unless additional permissions are\r\nexplicitly granted.\r\n</p>\r\n\r\n<h4>Why does an inactive record appear during editing?</h4>\r\n<p>\r\nThe system may include the currently selected inactive record so that an\r\nexisting equipment record does not lose its saved configuration.\r\n</p>',0,'circle-question',1,'{\"module\": \"Laboratory Configuration\", \"section\": \"laboratory-configuration-troubleshooting\", \"version\": \"1.0\", \"audience\": \"All authorized users\"}',1,'2026-08-03 00:29:15','2026-08-03 00:29:15');
